(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{}).num={"1":{"1":"И сказал Господь Моисею в Синайской пустыне, в Шатре Встречи, в первый день второго месяца второго года после ухода сынов Израилевых из Египта:","2":"«Сделайте перепись всей общины сынов Израилевых по семьям и родам – всех мужчин поименно с указанием общего числа,","3":"всех сынов Израилевых от двадцати лет и старше, способных носить оружие. Вы с Аароном должны их переписать, отряд за отрядом.","4":"Из каждого племени вам будет помогать один человек – предводитель родов этого племени.","5":"Вот имена людей, которые будут помогать вам: от племени Рувима – Элицур, сын Шедеура;","6":"от племени Симеона – Шелумиэл, сын Цуришаддая;","7":"от племени Иуды – Нахшон, сын Амминадава;","8":"от племени Иссахара – Нетанэл, сын Цуара;","9":"от племени Завулона – Элиав, сын Хелона;","10":"из потомков Иосифа: от племени Ефрема – Элишама, сын Аммихуда; от племени Манассии – Гамлиэл, сын Педацура;","11":"от племени Вениамина – Авидан, сын Гидеони ;","12":"от племени Дана – Ахиэзер, сын Аммишаддая;","13":"от племени Асира – Пагиэл, сын Охрана;","14":"от племени Гада – Эльясаф, сын Деуэла;","15":"от племени Неффалима – Ахира, сын Энана».","16":"Это самые уважаемые люди общины, вожди племен, главы кланов Израиля.","17":"Моисей и Аарон вместе с этими людьми, названными поименно,","18":"в первый день второго месяца собрали всю общину и занесли всех мужчин от двадцати лет и старше в списки по семьям и родам, поименно, с указанием общего числа,","19":"как и повелел Моисею Господь. Так в Синайской пустыне Моисей сделал перепись сынов Израилевых.","20":"Потомки Рувима, первенца Израилева, все мужчины от двадцати лет и старше, способные носить оружие, были занесены в поименные списки семей и родов, с указанием числа людей, –","21":"в племени Рувима было переписано сорок шесть тысяч пятьсот человек.","22":"Потомки Симеона, все мужчины от двадцати лет и старше, способные носить оружие, были занесены в поименные списки семей и родов, с указанием числа людей, –","23":"в племени Симеона было переписано пятьдесят девять тысяч триста человек.","24":"Потомки Гада, от двадцати лет и старше, способные носить оружие, были занесены в поименные списки семей и родов, с указанием числа людей, –","25":"в племени Гада было переписано сорок пять тысяч шестьсот пятьдесят человек.","26":"Потомки Иуды, от двадцати лет и старше, способные носить оружие, были занесены в поименные списки семей и родов, с указанием числа людей, –","27":"в племени Иуды было переписано семьдесят четыре тысячи шестьсот человек.","28":"Потомки Иссахара, от двадцати лет и старше, способные носить оружие, были занесены в поименные списки семей и родов, с указанием числа людей, –","29":"в племени Иссахара было переписано пятьдесят четыре тысячи четыреста человек.","30":"Потомки Завулона, от двадцати лет и старше, способные носить оружие, были занесены в поименные списки семей и родов, с указанием числа людей, –","31":"в племени Завулона было переписано пятьдесят семь тысяч четыреста человек.","32":"Переписаны были потомки Иосифа. Потомки Ефрема, от двадцати лет и старше, способные носить оружие, были занесены в поименные списки семей и родов, с указанием числа людей, –","33":"в племени Ефрема было переписано сорок тысяч пятьсот человек.","34":"Потомки Манассии, от двадцати лет и старше, способные носить оружие, были занесены в поименные списки семей и родов, с указанием числа людей, –","35":"в племени Манассии было переписано тридцать две тысячи двести человек.","36":"Потомки Вениамина, от двадцати лет и старше, способные носить оружие, были занесены в поименные списки семей и родов, с указанием числа людей, –","37":"в племени Вениамина было переписано тридцать пять тысяч четыреста человек.","38":"Потомки Дана, от двадцати лет и старше, способные носить оружие, были занесены в поименные списки семей и родов, с указанием числа людей, –","39":"в племени Дана было переписано шестьдесят две тысячи семьсот человек.","40":"Потомки Асира, от двадцати лет и старше, способные носить оружие, были занесены в поименные списки семей и родов, с указанием числа людей, –","41":"в племени Асира было переписано сорок одна тысяча пятьсот человек.","42":"Потомки Неффалима, от двадцати лет и старше, способные носить оружие, были занесены в поименные списки семей и родов, с указанием числа людей, –","43":"в племени Неффалима было переписано пятьдесят три тысячи четыреста человек.","44":"Таковы итоги переписи, проведенной Моисеем, Аароном и двенадцатью вождями Израиля, каждый из которых представлял роды своего племени.","45":"Всего сынов Израилевых, от двадцати лет и старше, способных носить оружие, записанных по родам,","46":"было шестьсот три тысячи пятьсот пятьдесят человек.","47":"Племя левитов не было включено в перепись.","48":"Господь сказал Моисею:","49":"«Племени Левия не включай в эту перепись, не пересчитывай левитов вместе с сынами Израилевыми.","50":"Поручи левитам смотреть за скинией Завета, за всеми ее принадлежностями и всем, что к ней относится. Пусть они носят скинию и все ее принадлежности, пусть смотрят за скинией. Они должны располагаться вокруг скинии.","51":"Когда скинию нужно снимать, пусть левиты ее разбирают, а когда скинию нужно ставить, пусть они ее собирают. Если же к скинии приблизится посторонний, его следует предать смерти.","52":"Пусть сыны Израилевы располагаются в стане по отрядам. Пусть каждый воин находится в своем войске, в своем отряде.","53":"А вокруг скинии Завета должны располагаться левиты, чтобы Гнев не пал на общину сынов Израилевых: левиты отвечают за скинию Завета».","54":"Сыны Израилевы в точности исполнили все, что Господь повелел Моисею."},"2":{"1":"Господь сказал Моисею и Аарону:","2":"«Пусть сыны Израилевы расположатся станом вокруг Шатра Встречи: каждый в своем войске и под боевыми стягами рода своего».","3":"Впереди, на восточной стороне, должно размещаться войско Иуды, с его отрядами. Вождь потомков Иуды – Нахшон, сын Амминадава.","4":"Его отряд насчитывает семьдесят четыре тысячи шестьсот человек.","5":"Рядом с ним – племя Иссахара. Вождь потомков Иссахара – Нетанэл, сын Цуара.","6":"Его отряд насчитывает пятьдесят четыре тысячи четыреста человек.","7":"Далее – племя Завулона. Вождь потомков Завулона – Элиав, сын Хелона.","8":"Его отряд насчитывает пятьдесят семь тысяч четыреста человек.","9":"Всего войско Иуды насчитывает в своих отрядах сто восемьдесят шесть тысяч четыреста человек. В походе они идут первыми.","10":"На южной стороне пусть размещается войско Рувима, с его отрядами. Вождь потомков Рувима – Элицур, сын Шедеура.","11":"Его отряд насчитывает сорок шесть тысяч пятьсот человек.","12":"Рядом с ним – племя Симеона. Вождь потомков Симеона – Шелумиэл, сын Цуришаддая.","13":"Его отряд насчитывает пятьдесят девять тысяч триста человек.","14":"Далее – племя Гада. Вождь потомков Гада – Эльясаф, сын Реуэла.","15":"Его отряд насчитывает сорок пять тысяч шестьсот пятьдесят человек.","16":"Всего войско Рувима насчитывает в своих отрядах сто пятьдесят одну тысячу четыреста пятьдесят человек. Пусть это войско идет вторым.","17":"Шатер Встречи и воинство левитов должны двигаться посреди других войск. Пусть все идут в том же порядке, в каком располагались на стоянке: каждый на своем месте, при своем войске.","18":"На западной стороне пусть размещается войско Ефрема, с его отрядами. Вождь потомков Ефрема – Элишама, сын Аммихуда.","19":"Его отряд насчитывает сорок тысяч пятьсот человек.","20":"Рядом с ним – племя Манассии. Вождь потомков Манассии – Гамлиэл, сын Педацура.","21":"Его отряд насчитывает тридцать две тысячи двести человек.","22":"Далее – племя Вениамина. Вождь потомков Вениамина – Авидан, сын Гидеони .","23":"Его отряд насчитывает тридцать пять тысяч четыреста человек.","24":"Всего войско Ефрема насчитывает в своих отрядах сто восемь тысяч сто человек. Пусть это войско идет третьим.","25":"На северной стороне пусть размещается войско Дана, с его отрядами. Вождь потомков Дана – Ахиэзер, сын Аммишаддая.","26":"Его отряд насчитывает шестьдесят две тысячи семьсот человек.","27":"Рядом с ним – племя Асира. Вождь потомков Асира – Пагиэл, сын Охрана.","28":"Его отряд насчитывает сорок одну тысячу пятьсот человек.","29":"Далее – племя Неффалима. Вождь потомков Неффалима – Ахира, сын Энана.","30":"Его отряд насчитывает пятьдесят три тысячи четыреста человек.","31":"Всего войско Дана насчитывает сто пятьдесят семь тысяч шестьсот человек. Пусть оно идет последним.","32":"Таковы итоги переписи сынов Израилевых, по родам. В их войске, со всеми его отрядами, было шестьсот три тысячи пятьсот пятьдесят человек;","33":"при этом левиты не были включены в перепись сынов Израилевых, как и повелел Господь Моисею.","34":"Сыны Израилевы в точности исполнили все, что Господь повелел Моисею: именно в таком порядке они располагались в стане – по войскам, именно в таком порядке двигались во время похода – каждый со своим племенем, со своим родом."},"3":{"1":"Вот потомки Аарона и Моисея, жившие в то время, когда Господь говорил с Моисеем на горе Синай.","2":"Имена сыновей Аарона: Надав (первенец Аарона), Авиуд, Элеазар и Итамар.","3":"Это сыновья Аарона, они были помазаны в священники и назначены для священнического служения.","4":"Надав и Авиуд умерли в Синайской пустыне, пред Господом, когда принесли для служения Господу чуждый огонь; детей у них не было. Элеазар и Итамар стали служить священниками еще при жизни Аарона, отца своего.","5":"Господь сказал Моисею:","6":"«Призови племя Левия и поставь их под начало священника Аарона; пусть они прислуживают ему.","7":"И за Аарона, и за всю общину они должны нести службу у Шатра Встречи – должны выполнять все работы при скинии.","8":"Неся службу за всех сынов Израилевых, они отвечают за все принадлежности Шатра Встречи и выполняют работу при скинии.","9":"Отдай левитов под начало Аарона и его сыновей; левиты отданы ему из числа сынов Израилевых.","10":"Поручи Аарону и его сыновьям нести священническое служение. Если же к святыне приблизится посторонний, его следует предать смерти».","11":"Господь сказал Моисею:","12":"«Я беру левитов из числа сынов Израилевых, Я забираю их Себе взамен первенцев Израильских – взамен первого плода материнского чрева. Левиты будут Моими,","13":"ибо всякий первенец – Мой. Когда Я уничтожил всех египетских первенцев, Я отделил и освятил для Себя всех первенцев в Израиле: и первенцев людей и первенцев скота. Они принадлежат Мне. Я – Господь».","14":"Господь сказал Моисею в Синайской пустыне:","15":"«Перепиши потомков Левия по родам и семьям; перепиши всех потомков Левия мужского пола старше одного месяца».","16":"И Моисей, по указанию Господа, переписал их так, как ему было велено.","17":"Вот имена сыновей Левия: Гершон, Кехат и Мерари .","18":"Вот имена сыновей Гершона: Ливни и Шими, с их родами.","19":"Сыновья Кехата: Амрам, Ицхар, Хеврон и Уззиэл, с их родами.","20":"Сыновья Мерари: Махли и Муши, с их родами. Таковы семьи и роды потомков Левия.","21":"От Гершона происходят род Ливни и род Шими. Это роды потомков Гершона.","22":"В них было переписано семь тысяч пятьсот потомков Гершона мужского пола старше одного месяца.","23":"Роды потомков Гершона должны располагаться позади скинии, на запад от нее.","24":"Вождь потомков Гершона – Эльясаф, сын Лаэла.","25":"Обязанности потомков Гершона при Шатре Встречи таковы: они отвечают за скинию, Шатер, его покрытие, полог на входе в Шатер Встречи,","26":"завесы двора, посреди которого стоят скиния и жертвенник, полог на входе во двор и веревки. Они выполняют всю необходимую при этом работу.","27":"От Кехата происходят род Амрама, род Ицхара, род Хеврона и род Уззиэла. Это роды потомков Кехата.","28":"В них было переписано восемь тысяч шестьсот потомков мужского пола старше одного месяца; они отвечают за священные предметы.","29":"Роды потомков Кехата должны располагаться на юг от скинии.","30":"Вождь потомков Кехата – Элицафан, сын Уззиэла.","31":"Они отвечают за ковчег, стол, светильник, жертвенники, используемую в богослужении священную утварь, а также за завесу. Они выполняют всю необходимую при этом работу.","32":"Верховный вождь племени Левия – Элеазар, сын священника Аарона; под его началом находятся те, кто отвечает за священные предметы.","33":"От Мерари происходят род Махли и род Муши. Это роды потомков Мерари.","34":"В них было переписано шесть тысяч двести потомков мужского пола старше одного месяца.","35":"Вождь потомков Мерари – Цуриэл, сын Авихаила. Они должны располагаться на север от скинии.","36":"Потомки Мерари хранят рамы скинии, перекладины, столбы, опоры и все принадлежности. Они выполняют всю необходимую при этом работу.","37":"Они отвечают также за столбы вокруг двора и их опоры, колышки и веревки.","38":"Перед скинией, на восток от Шатра Встречи, должны располагаться Моисей, Аарон и его сыновья. Они несут – за всех сынов Израилевых – службу в святилище; если же к святилищу приблизится посторонний, его следует предать смерти.","39":"Согласно переписи, которую провели Моисей и Аарон по указанию Господа, у левитов, по родам их, насчитывалось двадцать две тысячи человек мужского пола старше одного месяца.","40":"Господь сказал Моисею: «Перепиши у сынов Израилевых всех первенцев мужского пола старше одного месяца, определи их число.","41":"Я Господь! Возьми Мне левитов взамен первенцев сынов Израилевых, а скот левитов – взамен первенцев скота у сынов Израилевых».","42":"Моисей, как и повелел ему Господь, переписал всех первенцев у сынов Израилевых.","43":"Первенцев мужского пола старше одного месяца насчитывалось двадцать две тысячи двести семьдесят три человека.","44":"Господь сказал Моисею:","45":"«Возьми левитов взамен первенцев сынов Израилевых, а скот левитов вместо скота сынов Израилевых. Левиты будут Моими. Я – Господь.","46":"А так как первенцев сынов Израилевых на двести семьдесят три человека больше, чем левитов,","47":"то возьми за них выкуп: за каждого – по пять шекелей, в шекелях святилища (в каждом шекеле – двадцать гер).","48":"Отдай эти деньги – этот выкуп – Аарону и его сыновьям».","49":"Моисей собрал выкуп за тех первенцев сынов Израилевых, которые не были заменены левитами –","50":"тысячу триста шестьдесят пять шекелей серебра, в шекелях святилища.","51":"По указанию Господа – так велел ему Господь – Моисей отдал это серебро Аарону и его сыновьям."},"4":{"1":"Господь сказал Моисею и Аарону:","2":"«Перепишите среди левитов всех потомков Кехата, по семьям и родам,","3":"в возрасте от тридцати до пятидесяти лет, – всех, кто способен нести службу при Шатре Встречи.","4":"Потомки Кехата отвечают в Шатре Встречи за святыню святынь.","5":"При сборах в путь Аарон с сыновьями должны снять завесу и накрыть ею ковчег Завета,","6":"поверх укрыть ковчег покрытием из тонко выделанной кожи, поверх него накинуть одноцветное голубое покрывало – и вставить шесты.","7":"На стол, стоящий пред Господом, они должны будут накинуть голубое покрывало, а на нем пусть расставят блюда, ковши, чаши и кувшины для возлияний; хлеб регулярных приношений должен оставаться лежащим на столе.","8":"Пусть они накинут поверх всего этого багряное покрывало, а сверху укроют покрытием из тонко выделанной кожи – и вставят шесты.","9":"Они должны накрыть голубым покрывалом светильник, а также лампы светильника, щипцы, кадильницы и все сосуды для масла, которые употребляются при светильнике.","10":"Затем пусть укроют светильник и все его принадлежности покрытием из тонко выделанной кожи и положат на носилки.","11":"На золотой жертвенник пусть накинут голубое покрывало, поверх пусть укроют покрытием из тонко выделанной кожи – и вставят шесты.","12":"Пусть возьмут всю утварь, которая употребляется при богослужении в святилище, и закутают в голубое покрывало, поверх укроют покрытием из тонко выделанной кожи – и положат все это на носилки.","13":"Пусть очистят жертвенник от золы и накинут на него пурпуровое покрывало,","14":"а сверху пусть разложат все принадлежности жертвенника: совки для углей, вилки для мяса, лопатки, чаши для кропления кровью. Пусть укроют все это покрытием из тонко выделанной кожи – и вставят шесты.","15":"Когда будете собираться в дорогу, пусть сначала Аарон и его сыновья укроют священные предметы и всю священную утварь – и лишь после этого потомки Кехата могут подойти и взять ношу. А прикасаться к святыне потомки Кехата не должны, иначе они умрут. Носить эти принадлежности Шатра Встречи – обязанность потомков Кехата.","16":"Элеазар, сын священника Аарона, отвечает за масло для светильника, благовония для воскурений, регулярное хлебное приношение и масло для помазания. Он отвечает за скинию и за все, что находится в ней, – за священные предметы и священную утварь».","17":"Господь сказал Моисею и Аарону:","18":"«Смотрите, не допустите такого, чтобы роды потомков Кехата погибли и были вычеркнуты из племени левитов.","19":"А для того, чтобы они остались живы, – чтобы не умерли, приблизившись к святыне святынь, – Аарон и его сыновья должны сами прийти и дать каждому из потомков Кехата его ношу.","20":"Потомки Кехата не должны подходить к святыне и даже краем глаза видеть ее, иначе они умрут».","21":"Господь сказал Моисею:","22":"«Перепиши также потомков Гершона, по родам и семьям:","23":"перепиши всех в возрасте от тридцати до пятидесяти лет – всех, кто способен нести службу и выполнять работы при Шатре Встречи.","24":"Вот работа родов потомков Гершона, вот ноша, которую они должны переносить.","25":"Они несут полотнища скинии, Шатер Встречи, его покрытие, а также верхнее покрытие из тонко выделанной кожи, полог для входа в Шатер,","26":"завесы двора, полог для ворот двора, посреди которого стоят скиния и жертвенник, веревки к ним и все орудия для своей работы. Пусть выполняют всю необходимую при этом работу.","27":"Потомки Гершона будут работать и носить ношу по указанию Аарона и его сыновей. Вы поручаете им эту ношу, они отвечают за нее.","28":"Такова работа родов потомков Гершона при Шатре Встречи; они подчиняются Итамару, сыну священника Аарона.","29":"Потомков Мерари тоже перепиши, по семьям и родам:","30":"перепиши всех в возрасте от тридцати до пятидесяти лет – всех, кто способен нести службу и выполнять работы при Шатре Встречи.","31":"Вот за что они отвечают при Шатре Встречи: они несут рамы скинии, перекладины, столбы и опоры,","32":"столбы вокруг двора с их опорами, колышками и веревками, а также всю утварь. Пусть выполняют всю необходимую при этом работу. Вы поручаете им эту ношу, они отвечают за нее.","33":"Такова работа родов потомков Мерари – то, что они должны исполнять при Шатре Встречи под началом Итамара, сына священника Аарона».","34":"Моисей, Аарон и вожди общины переписали потомков Кехата, по семьям и родам,","35":"всех в возрасте от тридцати до пятидесяти лет – всех, кто мог нести службу и выполнять работы при Шатре Встречи.","36":"Всего их было записано, по родам, две тысячи семьсот пятьдесят человек.","37":"Таково число тех, кто был записан в родах потомков Кехата, – тех, кто должен служить при Шатре Встречи. Моисей и Аарон переписали их, как и повелел Господь через Моисея.","38":"Число потомков Гершона, со всеми их семьями и родами,","39":"в возрасте от тридцати до пятидесяти лет, – всех, кто мог нести службу и выполнять работы при Шатре Встречи, –","40":"составило, со всеми их семьями и родами, две тысячи шестьсот тридцать человек.","41":"Таково число тех, кто был записан в родах потомков Гершона, – тех, кто должен служить при Шатре Встречи. Моисей и Аарон переписали их, как и повелел Господь.","42":"Число потомков Мерари, со всеми их семьями и родами,","43":"в возрасте от тридцати до пятидесяти лет, – всех, кто мог нести службу и выполнять работы при Шатре Встречи, –","44":"составило три тысячи двести человек.","45":"Таково число тех, кто был записан в родах потомков Мерари. Моисей и Аарон переписали их, как и повелел Господь через Моисея.","46":"Всего же левитов, переписанных Моисеем, Аароном и вождями Израиля по семьям и родам, –","47":"всех в возрасте от тридцати до пятидесяти лет, – всех, кто мог нести службу при Шатре Встречи, работать и носить ношу, –","48":"насчитывалось восемь тысяч пятьсот восемьдесят человек.","49":"Они были переписаны Моисеем, по указанию Господа, и каждому была определена его работа и ноша. Все было сделано так, как повелел Господь Моисею."},"5":{"1":"Господь сказал Моисею:","2":"«Вели сынам Израилевым изгнать из стана всех, у кого проказа или истечение, и всех, кто нечист из – за прикосновения к мертвому телу.","3":"Изгоните таких людей, мужчин и женщин. Изгоните их за пределы стана, чтобы они не оскверняли стан, ибо там Я обитаю среди сынов Израилевых».","4":"Сыны Израилевы так и сделали – изгнали таких людей из стана. Как повелел Господь Моисею, так сыны Израилевы и сделали.","5":"Господь сказал Моисею:","6":"«Передай сынам Израилевым: если кто-нибудь, мужчина или женщина, согрешив против человека, совершит тем самым преступление против Господа, и ляжет на такого человека вина,","7":"то пусть согрешивший признается в своем проступке и полностью возместит пострадавшему ущерб, и еще прибавит к нему одну пятую и отдаст все это пострадавшему.","8":"Если у пострадавшего нет родственника, который мог бы это возмещение получить, то возмещение пойдет Господу, для священника, – наряду с бараном для искупительного обряда, посредством которого искупается вина согрешившего.","9":"Все подношения сынов Израилевых – все их священные дары – принадлежат священникам.","10":"Каждый из них оставляет себе принесенные ему священные дары; что отдано священнику, то ему и принадлежит».","11":"Господь сказал Моисею:","12":"«Передай сынам Израилевым: вот что надо делать, если женщина совершила преступление против мужа – изменила ему,","13":"и другой мужчина лег с нею и излил свое семя, но муж этого не видел; она осквернилась скрытно, свидетелей против нее нет, она не попалась,","14":"и все же муж, объятый духом ревности, ревнует оскверненную жену. Или если дух ревности обуял мужа, и он ревнует жену, а на самом деле она не осквернилась.","15":"В таких случаях муж должен привести жену к священнику и принести священнику одну десятую эфы ячменной муки в качестве приношения за нее. Муку не следует поливать оливковым маслом или посыпать ладаном, потому что это хлебное приношение ревности, это хлебное приношение обличения, оно обличает грех.","16":"Пусть священник приведет эту женщину и поставит ее пред Господом.","17":"Пусть он нальет в глиняный сосуд священной воды, возьмет немного земли с пола скинии и бросит ее в воду.","18":"Пусть поставит эту женщину пред Господом, распустит ей волосы и даст ей в руки хлебное приношение обличения – хлебное приношение ревности. В руках у священника должна быть горькая вода, которая несет проклятие,","19":"и он должен заклясть женщину такими словами: „Если не ложился с тобой другой мужчина, если ты не изменила мужу и не осквернилась, то пусть не повредит тебе эта горькая вода, несущая проклятие!","20":"Но если ты изменила мужу и осквернилась, если другой мужчина – не твой муж – лежал с тобою…\" –","21":"и тут священник должен проклясть эту женщину таким проклятием: „… пусть на твоем примере Господь покажет народу твоему, как исполняются проклятия: пусть Он сделает так, что утроба твоя выпадет, и чрево опухнет.","22":"Пусть эта несущая проклятие вода пройдет в самое твое нутро, заставит твое чрево опухать, а утробу – выпасть!\" И женщина вслух должна подтвердить: „Да будет так! Да будет так!\"","23":"Священник должен записать эти проклятия в свиток, смыть написанное в горькую воду","24":"и дать женщине выпить эту несущую проклятие горькую воду – чтобы эта несущая проклятие вода вошла в ее нутро и принесла с собой болезнь.","25":"Пусть священник возьмет у женщины хлебное приношение ревности, вознесет его пред Господом и поднесет к жертвеннику.","26":"Пусть возьмет горсть хлебного приношения, как его знаковую долю, и сожжет на жертвеннике. А женщине пусть даст выпить воду.","27":"Священник даст женщине выпить эту воду, и если она действительно осквернилась, совершив преступление против мужа, то эта несущая проклятие вода войдет в нее и принесет с собой болезнь: чрево ее опухнет, утроба выпадет, и станет она для народа своего примером того, как исполняются проклятия.","28":"А если женщина не осквернилась, если она чиста, то вода не повредит ей, и она сможет иметь детей.","29":"Таков закон о ревности – когда жена изменила мужу и осквернилась,","30":"или когда мужа обуял дух ревности и он подозревает жену. Пусть жену поставят пред Господом, и священник поступит с нею в соответствии с этим законом.","31":"Муж в этом случае не может быть призван к ответу; жена отвечает за свой грех»."},"6":{"1":"Господь сказал Моисею:","2":"«Передай сынам Израилевым: если кто-нибудь, мужчина или женщина, даст обет посвятить себя Господу – обет назорейства,","3":"то этот человек должен воздерживаться от вина и браги, не должен употреблять винный уксус или уксус из браги, не должен пить виноградный сок, не должен есть виноград или изюм.","4":"Во все время его назорейства ему нельзя есть ничего, что приготовлено из винограда, даже виноградные косточки или кожуру винограда.","5":"Все время, пока остается в силе его назорейский обет, он не должен стричь волосы. Пока не завершится срок, на который этот человек посвятил себя Господу, он свят: пусть отращивает волосы.","6":"В течение всего того времени, на которое он посвятил себя Господу, он не может приближаться к мертвому телу.","7":"Даже если умрет его отец или мать, брат или сестра, он не должен оскверняться прикосновением к ним, ибо на голове у него волосы назорейства, знак посвящения Богу.","8":"На все время своего назорейства он посвящен Господу.","9":"Если кто-нибудь неожиданно умрет рядом с ним, и этим осквернит волосы его назорейства, то в день, когда назорей снова станет чист, он должен остричь волосы. Пусть острижет волосы на седьмой день после осквернения.","10":"А на восьмой день пусть передаст священнику, у входа в Шатер Встречи, двух горлиц или двух голубей.","11":"Пусть священник принесет этих птиц в жертву (одну – как очистительную жертву, вторую – как всесожжение) и так искупит его от осквернения мертвым телом. И пусть назорей в тот же день снова освятит свою голову,","12":"даст пред Господом обет назорейства на новый срок и приведет годовалого ягненка как возместительную жертву. А прежний срок пропал, потому что его назорейство оказалось оскверненным.","13":"Вот закон для назорея. Когда завершится срок его назорейства, пусть приведут его ко входу в Шатер Встречи.","14":"Он должен доставить туда свое приношение Господу – годовалого ягненка без изъянов для всесожжения, годовалую овцу без изъянов как очистительную жертву, барана без изъянов для пиршественного жертвоприношения,","15":"корзину пресного хлеба из пшеничной муки (лепешки, смоченные оливковым маслом, и пресные коржи, намазанные оливковым маслом), а также надлежащее хлебное приношение и возлияния.","16":"Пусть священник поднесет это приношение к Господу и совершит очистительное жертвоприношение и всесожжение,","17":"а также пусть принесет Господу пиршественную жертву – барана, вместе с корзиной пресного хлеба. Пусть священник также совершит хлебное приношение и возлияние.","18":"Назорей должен остричь волосы у входа в Шатер Встречи, а затем взять эти волосы назорейства своего и бросить их в огонь, на котором сжигают пиршественную жертву.","19":"Когда назорей острижет волосы назорейства своего, священник должен взять сваренную переднюю ногу барана и пресную лепешку из корзины, а также пресный корж, и возложить все это на руки назорея.","20":"И пусть священник вознесет все это пред Господом. Это святыня, она принадлежит священнику, наряду с грудью жертвы, что была вознесена пред Господом, и бедром, что было поднесено в дар. После этого назорей может пить вино.","21":"Это закон для того, кто дал назорейский обет. Он делает приношение Господу в соответствии с правилом о назорействе, и сверх того – жертвует, что сможет пожертвовать. Он должен выполнить данный им обет в соответствии с правилом назорейства».","22":"Господь сказал Моисею:","23":"«Передай Аарону и его сыновьям: вот слова, которыми вы должны благословлять сынов Израилевых:","24":"„Да благословит тебя Господь, и да сохранит Он тебя!","25":"Да будет светел Его взор, обращенный к тебе, и да будет Он к тебе милостив!","26":"Да обратит к тебе Господь лицо Свое, и да пошлет тебе мир!\"","27":"Так запечатлеют они Мое имя на сынах Израилевых – и Я благословлю их»."},"7":{"1":"Когда Моисей установил скинию, он помазал и освятил скинию и всю ее утварь, а также жертвенник и всю его утварь. Все эти предметы он помазал и освятил.","2":"Затем вожди Израиля, предводители родов – вожди племен, проводившие перепись, – принесли свои приношения.","3":"Они поставили пред Господом в качестве приношения шесть повозок и двенадцать быков: по одной повозке от двух вождей и по одному быку от каждого вождя. Они поставили быков и повозки перед скинией.","4":"Господь сказал Моисею:","5":"«Прими это от них для работ при Шатре Встречи и распредели между левитами, кому что нужно для работы».","6":"Моисей принял повозки и быков и передал их левитам.","7":"Две повозки и четырех быков он отдал потомкам Гершона для их работы,","8":"а четыре повозки и восемь быков – потомкам Мерари для их работы под началом Итамара, сына священника Аарона.","9":"А потомкам Кехата он ничего не дал, ибо их служба – при священных предметах, которые они должны переносить на своих плечах.","10":"Когда совершилось помазание жертвенника, вожди принесли дары для его торжественного открытия. Они доставили свои дары к жертвеннику,","11":"и Господь сказал Моисею: «Пусть они поочередно, каждый вождь в свой день, приносят дары для торжественного открытия жертвенника».","12":"В первый день принес свои дары Нахшон, сын Амминадава, из племени Иуды.","13":"Вот его приношение: серебряное блюдо весом в сто тридцать шекелей и серебряная чаша весом в семьдесят шекелей, в шекелях святилища (блюдо и чаша были наполнены пшеничной мукой, смоченной оливковым маслом, для хлебного приношения);","14":"золотой ковш весом в десять шекелей, наполненный благовониями;","15":"бык, баран и годовалый ягненок – для всесожжения;","16":"козел – для очистительного жертвоприношения;","17":"два быка, пять баранов, пять козлов и пять годовалых ягнят – для пиршественного жертвоприношения. Таково было приношение Нахшона, сына Амминадава.","18":"Во второй день принес свои дары Нетанэл, сын Цуара, вождь племени Иссахара.","19":"Вот его приношение: серебряное блюдо весом в сто тридцать шекелей и серебряная чаша весом в семьдесят шекелей, в шекелях святилища (блюдо и чаша были наполнены пшеничной мукой, смоченной оливковым маслом, для хлебного приношения);","20":"золотой ковш весом в десять шекелей, наполненный благовониями;","21":"бык, баран и годовалый ягненок – для всесожжения;","22":"козел – для очистительного жертвоприношения;","23":"два быка, пять баранов, пять козлов и пять годовалых ягнят – для пиршественного жертвоприношения. Таково было приношение Нетанэла, сына Цуара.","24":"В третий день принес свои дары Элиав, сын Хелона, вождь потомков Завулона.","25":"Вот его приношение: серебряное блюдо весом в сто тридцать шекелей и серебряная чаша весом в семьдесят шекелей, в шекелях святилища (блюдо и чаша были наполнены пшеничной мукой, смоченной оливковым маслом, для хлебного приношения);","26":"золотой ковш весом в десять шекелей, наполненный благовониями;","27":"бык, баран и годовалый ягненок – для всесожжения;","28":"козел – для очистительного жертвоприношения;","29":"два быка, пять баранов, пять козлов и пять годовалых ягнят – для пиршественного жертвоприношения. Таково было приношение Элиава, сына Хелона.","30":"В четвертый день принес свои дары Элицур, сын Шедеура, вождь потомков Рувима.","31":"Вот его приношение: серебряное блюдо весом в сто тридцать шекелей и серебряная чаша весом в семьдесят шекелей, в шекелях святилища (блюдо и чаша были наполнены пшеничной мукой, смоченной оливковым маслом, для хлебного приношения);","32":"золотой ковш весом в десять шекелей, наполненный благовониями;","33":"бык, баран и годовалый ягненок – для всесожжения;","34":"козел – для очистительного жертвоприношения;","35":"два быка, пять баранов, пять козлов и пять годовалых ягнят – для пиршественного жертвоприношения. Таково было приношение Элицура, сына Шедеура.","36":"В пятый день принес свои дары Шелумиэл, сын Цуришаддая, вождь потомков Симеона.","37":"Вот его приношение: серебряное блюдо весом в сто тридцать шекелей и серебряная чаша весом в семьдесят шекелей, в шекелях святилища (блюдо и чаша были наполнены пшеничной мукой, смоченной оливковым маслом, для хлебного приношения);","38":"золотой ковш весом в десять шекелей, наполненный благовониями;","39":"бык, баран и годовалый ягненок – для всесожжения;","40":"козел – для очистительного жертвоприношения;","41":"два быка, пять баранов, пять козлов и пять годовалых ягнят – для пиршественного жертвоприношения. Таково было приношение Шелумиэла, сына Цуришаддая.","42":"В шестой день принес свои дары Эльясаф, сын Деуэла, вождь потомков Гада.","43":"Вот его приношение: серебряное блюдо весом в сто тридцать шекелей и серебряная чаша весом в семьдесят шекелей, в шекелях святилища (блюдо и чаша были наполнены пшеничной мукой, смоченной оливковым маслом, для хлебного приношения);","44":"золотой ковш весом в десять шекелей, наполненный благовониями;","45":"бык, баран и годовалый ягненок – для всесожжения;","46":"козел – для очистительного жертвоприношения;","47":"два быка, пять баранов, пять козлов и пять годовалых ягнят – для пиршественного жертвоприношения. Таково было приношение Эльясафа, сына Деуэла.","48":"В седьмой день принес свои дары Элишама, сын Аммихуда, вождь потомков Ефрема.","49":"Вот его приношение: серебряное блюдо весом в сто тридцать шекелей и серебряная чаша весом в семьдесят шекелей, в шекелях святилища (блюдо и чаша были наполнены пшеничной мукой, смоченной оливковым маслом, для хлебного приношения);","50":"золотой ковш весом в десять шекелей, наполненный благовониями;","51":"бык, баран и годовалый ягненок – для всесожжения;","52":"козел – для очистительного жертвоприношения;","53":"два быка, пять баранов, пять козлов и пять годовалых ягнят – для пиршественного жертвоприношения. Таково было приношение Элишамы, сына Аммихуда.","54":"В восьмой день принес свои дары Гамлиэл, сын Педацура, вождь потомков Манассии.","55":"Вот его приношение: серебряное блюдо весом в сто тридцать шекелей и серебряная чаша весом в семьдесят шекелей, в шекелях святилища (блюдо и чаша были наполнены пшеничной мукой, смоченной оливковым маслом, для хлебного приношения);","56":"золотой ковш весом в десять шекелей, наполненный благовониями;","57":"бык, баран и годовалый ягненок – для всесожжения;","58":"козел – для очистительного жертвоприношения;","59":"два быка, пять баранов, пять козлов и пять годовалых ягнят – для пиршественного жертвоприношения. Таково было приношение Гамлиэла, сына Педацура.","60":"В девятый день принес свои дары Авидан, сын Гидеони, вождь потомков Вениамина.","61":"Вот его приношение: серебряное блюдо весом в сто тридцать шекелей и серебряная чаша весом в семьдесят шекелей, в шекелях святилища (блюдо и чаша были наполнены пшеничной мукой, смоченной оливковым маслом, для хлебного приношения);","62":"золотой ковш весом в десять шекелей, наполненный благовониями;","63":"бык, баран и годовалый ягненок – для всесожжения;","64":"козел – для очистительного жертвоприношения;","65":"два быка, пять баранов, пять козлов и пять годовалых ягнят – для пиршественного жертвоприношения. Таково было приношение Авидана, сына Гидеони.","66":"В десятый день принес свои дары Ахиэзер, сын Аммишаддая, вождь потомков Дана.","67":"Вот его приношение: серебряное блюдо весом в сто тридцать шекелей и серебряная чаша весом в семьдесят шекелей, в шекелях святилища (блюдо и чаша были наполнены пшеничной мукой, смоченной оливковым маслом, для хлебного приношения);","68":"золотой ковш весом в десять шекелей, наполненный благовониями;","69":"бык, баран и годовалый ягненок – для всесожжения;","70":"козел – для очистительного жертвоприношения;","71":"два быка, пять баранов, пять козлов и пять годовалых ягнят – для пиршественного жертвоприношения. Таково было приношение Ахиэзера, сына Аммишаддая.","72":"В одиннадцатый день принес свои дары Пагиэл, сын Охрана, вождь потомков Асира.","73":"Вот его приношение: серебряное блюдо весом в сто тридцать шекелей и серебряная чаша весом в семьдесят шекелей, в шекелях святилища (блюдо и чаша были наполнены пшеничной мукой, смоченной оливковым маслом, для хлебного приношения);","74":"золотой ковш весом в десять шекелей, наполненный благовониями;","75":"бык, баран и годовалый ягненок – для всесожжения;","76":"козел – для очистительного жертвоприношения;","77":"два быка, пять баранов, пять козлов и пять годовалых ягнят – для пиршественного жертвоприношения. Таково было приношение Пагиэла, сына Охрана.","78":"В двенадцатый день принес свои дары Ахира, сын Энана, вождь потомков Неффалима.","79":"Вот его приношение: серебряное блюдо весом в сто тридцать шекелей и серебряная чаша весом в семьдесят шекелей, в шекелях святилища (блюдо и чаша были наполнены пшеничной мукой, смоченной оливковым маслом, для хлебного приношения);","80":"золотой ковш весом в десять шекелей, наполненный благовониями;","81":"бык, баран и годовалый ягненок – для всесожжения;","82":"козел – для очистительного жертвоприношения;","83":"два быка, пять баранов, пять козлов и пять годовалых ягнят – для пиршественного жертвоприношения. Таково было приношение Ахиры, сына Энана.","84":"Дары вождей Израиля по случаю торжественного открытия жертвенника, принесенные после помазания жертвенника, были таковы: двенадцать серебряных блюд, двенадцать серебряных чаш и двенадцать золотых ковшей","85":"(каждое блюдо весило сто тридцать шекелей, каждая чаша – семьдесят шекелей, а всего в блюдах и чашах было две тысячи четыреста шекелей серебра, в шекелях святилища,","86":"в двенадцати же золотых ковшах, наполненных благовониями и весивших десять шекелей каждый, в шекелях святилища, было сто двадцать шекелей золота);","87":"скот для всесожжении – двенадцать быков, двенадцать баранов и двенадцать годовалых ягнят, а также надлежащее хлебное приношение; двенадцать козлов для очистительного жертвоприношения;","88":"скот для пиршественного жертвоприношения – двадцать четыре быка, шестьдесят баранов, шестьдесят козлов и шестьдесят годовалых ягнят. Таковы были дары по случаю торжественного открытия жертвенника, принесенные после его помазания.","89":"Когда Моисей входил в Шатер Встречи, чтобы говорить с Господом, то он слышал голос, звучавший между двумя херувимами, над навершием, что накрывает ковчег Завета. Так Господь говорил с Моисеем."},"8":{"1":"Господь сказал Моисею:","2":"«Вели Аарону, пусть расставит лампы, так чтобы семь ламп освещали пространство перед светильником».","3":"Аарон так и сделал – расставил лампы на светильнике, как повелел Господь Моисею.","4":"Светильник же был чеканный, из золота; чеканный от ствола до лепестка. Моисей изготовил этот светильник по образцу, который показал ему Господь.","5":"Господь сказал Моисею:","6":"«Отдели левитов от сынов Израилевых и соверши над ними обряд очищения.","7":"Вот что ты должен сделать для их очищения: окропи их водой очищения, пусть они обреют себе все тело и постирают одежду – и тогда они станут чисты.","8":"Пусть они возьмут быка и надлежащее хлебное приношение из пшеничной муки, смоченной оливковым маслом. Возьми также второго быка, для очистительного жертвоприношения.","9":"Поставь левитов перед Шатром Встречи и собери всю общину сынов Израилевых.","10":"Когда ты поставишь левитов пред Господом, пусть сыны Израилевы возложат на них руки,","11":"и пусть Аарон вручит левитов Господу как дар сынов Израилевых, вознесенный пред Господом. После этого левиты могут совершать служение Господу.","12":"Пусть левиты возложат руки на головы быков, и эти быки будут принесены в жертву (один бык – как очистительная жертва, другой – как всесожжение Господу). Это будет искупительным обрядом для левитов.","13":"Поставь левитов под начало Аарона и его сыновей, вручи им левитов как дар, вознесенный пред Господом.","14":"Отдели левитов от сынов Израилевых: левиты должны принадлежать Мне.","15":"После этого, когда ты их очистишь и вручишь их – как дар вознесенный пред Господом – левиты могут подойти и служить при Шатре Встречи.","16":"Они отданы Мне из числа сынов Израилевых. Я взял их Себе взамен первого плода материнского чрева, вместо всех первенцев сынов Израилевых.","17":"Все первенцы сынов Израилевых – и первенцы людей, и первенцы скота – принадлежат Мне: Я отделил и освятил их для Себя, когда убил всех первенцев Египта.","18":"А теперь Я взял Себе левитов взамен первенцев сынов Израилевых.","19":"Отделив левитов от всех прочих сынов Израилевых, Я отдал их Аарону и его сыновьям; левиты должны, за всех сынов Израилевых, совершать служение при Шатре Встречи; они будут служить искупительной жертвой за сынов Израилевых. А сыны Израилевы не будут приближаться к святыне, чтобы их не постигла кара».","20":"Моисей, Аарон и вся община сынов Израилевых сделали с левитами все в точности так, как повелел Моисею Господь.","21":"Левиты очистились и постирали свои одежды. Аарон вручил их Господу как дар, вознесенный пред Ним, и совершил над ними искупительный обряд, очистив их от нечистоты.","22":"После этого левиты стали служить при Шатре Встречи под началом Аарона и его сыновей. С левитами все было сделано так, как повелел Моисею Господь.","23":"Господь сказал Моисею:","24":"«Вот правило для левитов: с двадцати пяти лет левит должен нести служение при Шатре Встречи,","25":"а в пятьдесят лет он свое служение прекращает – и уже не должен служить.","26":"Он может помогать своим собратьям, отвечающим за Шатер Встречи, но сам более не должен служить. Такие распоряжения ты должен отдать о служении левитов»."},"9":{"1":"И сказал Господь Моисею в Синайской пустыне, в первое новолуние второго года после ухода сынов Израилевых из Египта:","2":"«Пусть сыны Израилевы совершают Пасху в положенный срок.","3":"Совершайте ее в положенный срок, в четырнадцатый день этого месяца, с наступлением сумерек. Совершайте ее по всем предписаниям и законам».","4":"Моисей повелел сынам Израилевым совершить Пасху,","5":"и они совершили Пасху в Синайской пустыне, в четырнадцатый день первого месяца, с наступлением сумерек. Сыны Израилевы сделали все в точности так, как повелел Моисею Господь.","6":"Были там люди, которые оказались нечисты из – за прикосновения к мертвому телу и не смогли в этот день совершить Пасху. Они в тот же день пришли к Моисею и Аарону","7":"и сказали: «Мы нечисты из – за прикосновения к мертвому телу. Неужели мы не можем совершить приношение Господу в положенный срок, вместе со всеми сынами Израилевыми?»","8":"Моисей ответил: «Постойте здесь, а я пойду и услышу от Господа, как Он распорядится о вас».","9":"Господь сказал Моисею:","10":"«Передай сынам Израилевым: если кто-то из вас или ваших потомков осквернится прикосновением к мертвому телу или окажется далеко от дома, в пути, он все равно должен совершить Пасху Господню.","11":"Пусть он совершит ее в четырнадцатый день второго месяца, с наступлением сумерек. Пусть он ест пасхального ягненка с пресным хлебом и горькими травами.","12":"Пусть не оставляет его мясо до утра и костей его не ломает. Он должен исполнить все предписания о Пасхе!","13":"А тот, кто был чист и не был в пути, но Пасху не совершил, будет истреблен и отторгнут от народа своего за то, что не совершил приношение Господу в положенный срок; он будет наказан за свой грех.","14":"Если живущий среди вас переселенец желает совершить Пасху Господню, он должен исполнить все предписания и законы о Пасхе. Одинаковые правила должны быть у вас и для переселенца, и для уроженца вашей страны».","15":"Когда скиния была поставлена, то всю скинию – Шатер Завета – окутало облако, а с вечера до утра словно бы огонь горел над скинией.","16":"С тех пор так было все время: скинию окутывало облако, а ночью словно бы огонь горел.","17":"Всякий раз, когда облако поднималось от Шатра вверх, сыны Израилевы отправлялись в путь; там, где облако останавливалось, они разбивали стан.","18":"По указанию Господа сыны Израилевы отправлялись в путь и по указанию Господа останавливались; пока облако покоилось на скинии, они оставались на месте.","19":"Если облако долгое время пребывало на скинии, сыны Израилевы исполняли повеление Господа и не трогались с места.","20":"А если облако покоилось на скинии лишь несколько дней, то сыны Израилевы оставались на месте по указанию Господа, а затем по указанию Господа отправлялись в путь.","21":"Если облако стояло на месте лишь с вечера до утра, то утром, когда оно поднималось, они сразу отправлялись в путь. Когда облако стояло на месте один день и одну ночь, а затем поднималось – они сразу отправлялись в путь.","22":"Сколько бы облако ни пребывало на скинии – два дня, или месяц, или еще дольше – сыны Израилевы все это время оставались на месте и не отправлялись в путь, а когда облако поднималось, они сразу отправлялись в путь.","23":"По указанию Господа они останавливались и по указанию Господа отправлялись в путь; так они исполняли повеление Господа, данное через Моисея."},"10":{"1":"Господь сказал Моисею:","2":"«Сделай две трубы. Из чеканного серебра сделай их. Они будут служить тебе, чтобы созывать общину и чтобы подавать сигнал к выступлению.","3":"Если протрубят в обе трубы, вся община должна собраться к тебе, ко входу в Шатер Встречи,","4":"а если протрубят в одну, к тебе должны собраться только вожди, главы кланов Израиля.","5":"Когда протрубят сигнал с трелью, пусть отправляются в путь те войска, что расположились на восточной стороне,","6":"а когда во второй раз протрубят сигнал с трелью – те войска, что на южной стороне. По сигналу с трелью войска снимаются с места.","7":"А чтобы созвать собрание, трубите просто, без трелей.","8":"Трубить в трубы должны священники, потомки Аарона, – это вам предписание навеки, соблюдайте его из рода в род.","9":"Когда будете воевать на своей земле с напавшими на вас врагами, то трубите в трубы – это будет напоминанием о вас пред Господом, вашим Богом, и вам будет дарована победа.","10":"В дни радости – в праздники и новолуния – трубите в трубы, принося жертвы всесожжения и пиршественные жертвы. Это будет напоминанием о вас пред Богом вашим. Я – Господь, ваш Бог».","11":"Во второй год, в двадцатый день второго месяца, облако поднялось над скинией Завета,","12":"и сыны Израилевы двинулись в путь, покидая Синайскую пустыню. Облако остановилось в пустыне Паран.","13":"Это был первый раз, когда они выступили в поход, следуя указаниям Господа, данным через Моисея.","14":"Сначала в путь пустилось войско потомков Иуды, отряд за отрядом. Их возглавлял Нахшон, сын Амминадава.","15":"Отряд племени Иссахара возглавлял Нетанэл, сын Цуара.","16":"Отряд племени Завулона возглавлял Элиав, сын Хелона.","17":"Затем была разобрана скиния. Потомки Гершона и потомки Мерари отправились в путь, неся скинию.","18":"Затем выступило войско Рувима, отряд за отрядом. Их возглавлял Элицур, сын Шедеура.","19":"Отряд племени Симеона возглавлял Шелумиэл, сын Цуришаддая.","20":"Отряд племени Гада возглавлял Эльясаф, сын Деуэла.","21":"Затем отправились в путь потомки Кехата, неся священные предметы. (К их приходу на новое место скинию уже должны были установить.)","22":"Затем выступило войско потомков Ефрема, отряд за отрядом. Их возглавлял Элишама, сын Аммихуда.","23":"Отряд племени Манассии возглавлял Гамлиэл, сын Педацура.","24":"Отряд племени Вениамина возглавлял Авидан, сын Гидеони.","25":"Последним выступило войско потомков Дана, отряд за отрядом. Их возглавлял Ахиэзер, сын Аммишаддая.","26":"Отряд племени Асира возглавлял Пагиэл, сын Охрана.","27":"Отряд племени Неффалима возглавлял Ахира, сын Энана.","28":"Таков был порядок движения сынов Израилевых, когда они выступили в поход, отряд за отрядом.","29":"Моисей сказал Ховаву, сыну Реуэла – мидьянитянина, тестя Моисеева: «Мы направляемся в ту землю, которую Господь обещал нам отдать. Идем с нами, и мы позаботимся о том, чтобы тебе было хорошо, ведь Господь обещает сделать Израилю много добра!»","30":"Но тот ответил: «Нет, я вернусь в свою страну, на родину». –","31":"«Не оставляй нас! – сказал Моисей. – Ты умеешь находить нам удобные места для стоянок в пустыне, ты будешь нашими глазами.","32":"Если ты с нами пойдешь и Господь сотворит нам добро, мы позаботимся, чтобы и тебе было хорошо…»","33":"Отправившись от горы Господней, они шли три дня, и все три дня ковчег договора с Господом двигался впереди, чтобы находить и указывать им места для ночлега.","34":"А днем, когда они покидали стоянку, облако Господне поднималось над ними.","35":"Когда ковчег трогался в путь, Моисей говорил: «Вперед, о Господь! Пусть рассеются Твои враги, пусть недруги Твои бегут прочь!»","36":"А когда ковчег останавливался, Моисей говорил: «Вернись, Господь бесчисленных тысяч сынов Израилевых!»"},"11":{"1":"Народ роптал и жаловался, и Господь это слышал. А когда услышал, то разгорелся Его гнев, и запылал огонь Господень, так что дальняя часть стана загорелась.","2":"Народ воззвал к Моисею, тот помолился Господу, и огонь утих.","3":"Место это они назвали Тавера, ибо там среди них запылал огонь Господень.","4":"У разноплеменных людей, примкнувших к сынам Израилевым, были всевозможные прихоти. Вслед за ними снова принялись плакать и сыны Израилевы. «Мяса бы сейчас поесть! – говорили они. –","5":"Мы помним, как в Египте нам бесплатно давали рыбу, и огурцы, и дыни, и лук – порей, и репчатый лук, и чеснок!","6":"А здесь ничего нет, видим одну только манну, от которой нас уже тошнит».","7":"Манна походит на кориандровое семя, а по цвету она напоминает сухую благовонную смолу.","8":"Люди ходили и собирали манну, перемалывали ее ручными жерновами или толкли в ступе, а потом варили в горшке или пекли из нее лепешки, схожие по вкусу с лепешками на оливковом масле.","9":"Ночью, когда в стане выпадала роса, вместе с нею выпадала и манна.","10":"Услышал Моисей, что народ плачет – каждая семья плакала у входа в свой шатер. И разгорелся гнев Господа, и горько стало Моисею,","11":"и сказал он Господу: «Зачем Ты мучишь меня, раба Своего, чем я неугоден Тебе? Зачем Ты возложил на меня бремя заботы об этом народе?","12":"Разве я зачал этот народ, разве я родил его на свет? Почему же Ты велел мне нести этот народ на руках, как нянька несет малое дитя, – нести их в ту землю, о которой Ты клялся их отцам?","13":"Где я возьму мясо для всего этого народа? А они плачут и требуют, чтобы я накормил их мясом!","14":"Не могу я один нести бремя заботы об этом народе, слишком тяжела для меня эта ноша.","15":"Если Ты и дальше хочешь так поступать со мною, то окажи милость, убей меня, чтобы мне не видеть беды, в которую я попал!»","16":"И Господь сказал Моисею: «Собери ко Мне семьдесят старейшин Израиля, людей, которые тебе известны как старейшины и старосты. Приведи их к Шатру Встречи, и пусть они станут перед Шатром вместе с тобою.","17":"Я сойду и буду там говорить с тобою. Я возьму часть духа, который пребывает на тебе, и передам старейшинам, чтобы они несли вместе с тобой бремя заботы о народе, тебе уже не придется нести это бремя одному.","18":"А народу скажи: освятитесь, готовьтесь к завтрашнему дню, когда вы будете есть мясо. Вы плакали пред Господом, говорили, что вам хочется мяса, что в Египте вам было лучше. Так вот, Господь даст вам мяса! Вы наедитесь досыта!","19":"Вы будете есть мясо и не день, и не два, и не пять дней, не десять и не двадцать,","20":"а целый месяц – пока оно не полезет у вас из ноздрей, пока не станет для вас отвратительно! Так вам будет за то, что отвергнув Господа, который обитает среди вас, вы плакали пред Ним и спрашивали: „Зачем мы ушли из Египта?\"»","21":"Моисей сказал: «Здесь, со мною, шестьсот тысяч пеших воинов, а Ты говоришь, что дашь им мяса на целый месяц!","22":"Если зарезать весь мелкий и крупный скот – разве хватит его? Если поймать всю рыбу в море, разве ее хватит?»","23":"Но Господь ответил Моисею: «Неужели бессильна рука Господня? Что же, смотри, сбудется Мое слово или нет!»","24":"Моисей вышел и передал народу слова Господа. Собрав семьдесят старейшин, Моисей велел им стать вокруг Шатра.","25":"Господь сошел в облаке и говорил с Моисеем, а затем взял часть духа, пребывавшего на Моисее, и передал семидесяти старейшинам. Когда дух сошел на старейшин, они начали пророчествовать, потом перестали.","26":"Еще на двоих человек сошел дух, хотя эти двое оставались в стане. Одного из них звали Элдад, другого – Медад. Оба они были записаны в списке старейшин, но к Шатру не вышли. И вот, они начали пророчествовать прямо в стане.","27":"Прибежал слуга и сказал Моисею: «Элдад и Медад пророчествуют в стане!»","28":"Иисус Навин, который с юности был помощником Моисея, воскликнул: «Моисей, господин мой, вели им умолкнуть!»","29":"Но Моисей сказал ему: «Это меня ты так ревниво защищаешь? О, если бы все в народе Господнем были пророками! О если бы Господь послал на них дух Свой!»","30":"И Моисей вернулся в стан, вместе со старейшинами Израиля.","31":"Поднялся ветер, посланный Господом, и принес в стан стаю перепелов со стороны моря. Вокруг стана, на день пути во все стороны, лежали кучи перепелов высотой в два локтя.","32":"Народ принялся собирать перепелов; их собирали весь тот день, и всю ночь, и весь следующий день – каждый набрал не меньше десяти хомеров. Потом перепелов разложили вокруг стана.","33":"Но не успели они еще прожевать это мясо, не успели его доесть, как разгорелся на них гнев Господень – и поразил их Господь жестоким мором.","34":"Это место они назвали Киврот – ха – Таава, потому что там похоронили привередливых.","35":"Из Киврот – ха – Таавы сыны Израилевы пришли в Хацерот. Там они сделали остановку."},"12":{"1":"Мирьям и Аарон упрекали Моисея за женитьбу на женщине из Куша (Моисей взял себе жену родом из Куша).","2":"Они сказали: «Разве только с Моисеем говорил Господь? Разве с нами Он не говорил?» И Господь услышал эти речи.","3":"(А Моисей был очень кротким человеком, самым кротким из всех людей на земле.)","4":"И внезапно сказал Господь Моисею, Аарону и Мирьям: «Идите втроем в Шатер Встречи». Они пошли,","5":"и сошел к ним Господь, как столп облачный, стал у входа в Шатер и позвал Аарона и Мирьям. Когда они приблизились,","6":"Господь сказал: «Слушайте Мои слова! Если есть средь вас пророк Господень, Я ему открываюсь в виденьях, говорю с ним посредством снов.","7":"С рабом Моим, Моисеем, – не так: все достоянье Мое Я доверил ему!","8":"Я говорю с ним лицом к лицу, Я являюсь ему без загадок, и образ Господа видит он. Как же вы не побоялись укорять раба Моего, Моисея?»","9":"И гнев Господа разгорелся на них. Господь ушел прочь,","10":"облако удалилось от Шатра. А Мирьям вся покрылась проказой, как снегом. Аарон повернулся к Мирьям и увидел, что она вся покрыта проказой.","11":"Тогда он сказал Моисею: «Господин мой! Не карай нас за грех, который мы совершили по глупости своей!","12":"Не допусти, чтобы Мирьям осталась такою, подобной мертворожденному ребенку, который вышел из материнского чрева наполовину сгнившим».","13":"«Боже! Исцели ее!» – воззвал Моисей к Господу.","14":"Господь сказал Моисею: «Если бы ее отец плюнул ей в лицо, она семь дней пребывала бы опозоренной. Так что изгоните ее из стана на семь дней, а потом пусть вернется в стан».","15":"И Мирьям изгнали из стана на семь дней. Сыны Израилевы не трогались в путь, пока она не вернулась."},"13":{"1":"Затем они покинули Хацерот, пришли в пустыню Паран, и там сделали остановку.","2":"Господь сказал Моисею:","3":"«Пошли людей осмотреть Ханаан – страну, которую я отдаю сынам Израилевым. Отправьте по одному человеку от племени, и пусть это будут вожди».","4":"И Моисей, по велению Господа, послал вперед из пустыни Паран несколько человек; все они были предводителями сынов Израилевых.","5":"Вот их имена: от племени Рувима – Шаммуа, сын Заккура;","6":"от племени Симеона – Шафат, сын Хори ;","7":"от племени Иуды – Калев, сын Иефунне ;","8":"от племени Иссахара – Игал, сын Иосифа;","9":"от племени Ефрема – Осия Навин;","10":"от племени Вениамина – Палти, сын Рафу ;","11":"от племени Завулона – Гаддиэл, сын Соди ;","12":"от племени Иосифа – от племени Манассии – Гадди, сын Суси ;","13":"от племени Дана – Аммиэл, сын Гемалли ;","14":"от племени Асира – Сетур, сын Михаила;","15":"от племени Неффалима – Нахби, сын Вафси ;","16":"от племени Гада – Геуэл, сын Махи .","17":"Это имена людей, которых Моисей отправил осмотреть страну. (А Осии Навину Моисей дал новое имя – Иисус.)","18":"Отправляя их осмотреть Ханаан, Моисей сказал им: «Идите через Негев в нагорную страну!","19":"Осмотрите эту землю и узнайте, какова она. Каков живущий там народ: силен он или слаб, малочислен или многочислен?","20":"Какова страна этого народа: хороша она или плоха? Где живут эти люди: в селах или в укрепленных городах?","21":"Какова там земля: плодородна она или бесплодна? Растут ли там деревья? Непременно постарайтесь принести с собою плоды этой земли». (То была пора, когда собирают первый урожай винограда.)","22":"Посланные осмотрели страну, от пустыни Цин до Рехова, что близ Лево–Хамата.","23":"Пройдя Негев, они достигли Хеврона, где обитали Ахиман, Шешай и Талмай, сыны Анака. (Хеврон был основан на семь лет раньше, чем город Цоан в Египте.)","24":"Они пришли в долину Эшкол и срезали там виноградную лозу с одной гроздью – но такой, что требовалось двое человек, чтобы нести ее на шесте! Они также набрали там гранатов и смокв.","25":"(Это место было названо долиной Эшкол в память о грозди, которую срезали там сыны Израилевы.)","26":"Через сорок дней посланцы вернулись, осмотрев всю страну.","27":"Придя в Кадеш, что в пустыне Паран, к Моисею, Аарону и всей общине сынов Израилевых, они рассказали Моисею, Аарону и всей общине о том, что видели, и показали плоды той земли.","28":"Так говорили посланцы Моисею: «Мы побывали в той стране, в которую ты нас отправил. Эта земля поистине источает молоко и мед. Вот ее плоды!","29":"Однако народ, живущий там, силен, а города большие и укрепленные. Мы даже видели там сынов Анака!","30":"Амалекитяне живут в Негеве, хетты, евусеи и амореи – в горах, а ханаанеи – у моря и вдоль Иордана».","31":"Калев пытался успокоить народ, окружавший Моисея. «Пойдемте и овладеем этой страной! – говорил он. – Мы сможем победить их!»","32":"Но те, кто ходил туда вместе с Калевом, возражали: «Не можем мы воевать с этим народом, он сильнее нас!»","33":"Они стали распускать среди сынов Израилевых дурную молву о земле, которую осматривали. «Земля, по которой мы прошли, – говорили они, – пожирает тех, кто поселится на ней! Все люди, которых мы там видели, были огромного роста.","34":"Мы видели там исполинов (сыны Анака – из рода исполинов). Рядом с ними мы чувствовали себя кузнечиками, и они смотрели на нас, как на кузнечиков»."},"14":{"1":"И вся община подняла громкий крик. Всю следующую ночь народ плакал.","2":"Сыны Израилевы роптали на Моисея и Аарона. Вся община говорила Моисею и Аарону: «Уж лучше бы мы умерли в Египте! Уж лучше бы мы умерли в этой пустыне!","3":"Зачем Господь ведет нас в эту страну? Чтобы мы погибли от меча? Жены наши и дети попадут в неволю! Не лучше ли нам вернуться в Египет?»","4":"И люди стали говорить между собою: «Повернем назад, вернемся в Египет!»","5":"Моисей и Аарон простерлись ниц пред общиной сынов Израилевых.","6":"Иисус Навин и Калев, сын Иефунне, ходившие вместе с другими разведчиками осматривать страну, разорвали свои одежды","7":"и стали убеждать общину сынов Израилевых: «Та земля, по которой мы прошли, ее осматривая, очень, очень хороша!","8":"Если мы будем угодны Господу, Он приведет нас туда и отдаст нам эту землю, источающую молоко и мед.","9":"Только не бунтуйте против Господа! А людей той страны не бойтесь – мы их одолеем! Они лишились своей защиты, а с нами Господь. Не бойтесь их!»","10":"Но община хотела побить их камнями. И тогда у Шатра Встречи, предстала сынам Израилевым слава Господня.","11":"Господь сказал Моисею: «До каких пор этот народ все будет смотреть на Меня с пренебрежением? Будет не верить Мне – несмотря на все знамения, которые Я совершил среди них?","12":"Я поражу их чумой и уничтожу. А от тебя Я произведу новый народ, который будет еще многочисленнее и сильнее».","13":"Но Моисей сказал Господу: «Про это услышат египтяне; ведь из – под их власти Ты, силой Своей, увел этот народ!","14":"Они расскажут про случившееся жителям этой страны. А те уже слышали, что Ты, Господь, пребываешь среди этого народа и являешься здесь воочию, что облако Твое стоит над этим народом, что Ты Сам идешь впереди них, днем в облачном столпе, а ночью в столпе огненном.","15":"Если Ты истребишь этот народ до последнего человека, то все народы, до которых дошел слух о Тебе, скажут так:","16":"„Не смог Господь привести этот народ в страну, которую поклялся отдать им, – и поэтому истребил их в пустыне!\"","17":"Но да будет прославлена сила Владыки! Ты ведь Сам сказал:","18":"„Господь терпелив и милостив! Он терпит провинности и грехи, но виновного Он не признает невинным. Он карает детей за грехи отцов, карает внуков и правнуков!\"","19":"Прости же, по великой милости Своей, грех этого народа, как Ты прощал их со дня ухода из Египта и по сей день!»","20":"Тогда Господь сказал: «Я прощаю их, по твоей просьбе.","21":"Но клянусь Собою и славой Господней, наполняющей всю землю:","22":"никто из тех, кто, видя славу Мою и знамения, совершенные Мною в Египте и в пустыне, продолжали Меня не слушать и десять раз Меня испытывали, –","23":"никто из них не увидит страны, о которой Я клялся их отцам. Никто из тех, кто мне не верит, не увидит эту страну!","24":"Но не таков по духу Мой раб Калев: он остался Мне верен, и в награду Я приведу его в ту страну, где он уже побывал. Его потомство будет владеть этой страной!","25":"…Долины той страны заселены амалекитянами и ханаанеями; завтра поворачивайте и идите в пустыню, по дороге к морю Суф».","26":"Господь сказал Моисею и Аарону:","27":"«Доколе эта община негодяев все будет на Меня роптать? Я ведь слышу, как жалуются сыны Израилевы!","28":"Передай им: „Клянусь Собою, – говорит Господь, – чего вы хотели – то вы от Меня и получите!","29":"Ваши тела останутся в этой пустыне – тела всех, кто исчислен в ваших родословиях, от двадцати лет и старше, тела всех, кто роптал на Меня!","30":"Никто из вас не войдет в ту страну, в которой Я поклялся поселить вас, – никто, кроме Калева, сына Иефунне, и Иисуса Навина.","31":"А вот детей ваших, за которых вы боялись, как бы они не попали в плен, – их Я приведу в страну, которую вы отвергли. Они увидят, что это за страна!","32":"Ваши тела останутся в этой пустыне,","33":"и ваши дети будут пасти скот в этой пустыне сорок лет: они будут нести наказание за вашу измену, пока последний из вас не погибнет в пустыне.","34":"Сорок дней вы осматривали страну, и по числу этих дней, по году за день, вы будете нести наказание за свои грехи: сорок лет! Тогда вы узнаете, что значит изменять Мне\".","35":"Это говорю Я, Господь! Клянусь, что так Я и поступлю с этой общиной негодяев, взбунтовавшихся против Меня. Они найдут свой конец в этой пустыне! Они здесь и умрут!»","36":"Люди, которых Моисей отправил осмотреть эту страну, и которые, вернувшись, распустили о ней дурные слухи, так что вся община стала роптать на Моисея, –","37":"все люди, распускавшие злые слухи об этой стране, – умерли от мора. Господь поразил их.","38":"Из всех, кто ходил осматривать страну, в живых остались лишь Иисус Навин и Калев, сын Иефунне.","39":"Моисей передал сынам Израилевым слова Господа, и скорбь объяла их.","40":"На следующее утро они направились в горы, говоря: «Мы пойдем туда, куда нам велел идти Господь. Мы согрешили!»","41":"Моисей сказал: «Зачем вы не следуете указанию Господа? Вас ждет поражение.","42":"Раз Господь не с вами, то не ходите, а иначе враги одолеют вас.","43":"Там, впереди, – амалекитяне и ханаанеи; вы падете от меча! Ведь вы отвернулись от Господа, и Господь не с вами».","44":"Но те самонадеянно направились в горы, а ковчег договора с Господом и Моисей оставались в стане.","45":"Амалекитяне и ханаанеи, обитатели этих гор, спустились им навстречу, и разбили их, и гнали их до самой Хормы."},"15":{"1":"Господь сказал Моисею:","2":"«Передай сынам Израилевым: когда вы придете в страну, в которой вы будете жить, в страну, которую Я вам отдаю,","3":"и станете там приносить в дар Господу животное из крупного или мелкого скота – будь то всесожжение, или жертва по обету, или добровольная пиршественная жертва, или жертва по случаю праздника – когда вы станете возносить Господу благоуханный дым, приятный Ему, –","4":"пусть жертва Господу обязательно сопровождается хлебным приношением. Это одна десятая эфы пшеничной муки, которая смочена четвертью гина оливкового масла.","5":"Вместе со всесожжением и жертвой совершай и возлияние. Это четверть гина вина. Столько полагается на каждого ягненка.","6":"Если приносишь в жертву барана, хлебное приношение должно быть две десятых эфы пшеничной муки, которая смочена третью гина оливкового масла,","7":"а возлияние – треть гина вина. Это будет благоуханный дым, приятный Господу.","8":"Если приносишь в жертву Господу быка – будь то всесожжение, или жертва по обету, или пиршественная жертва –","9":"то на этого быка полагается хлебное приношение – три десятых эфы пшеничной муки, которая смочена половиной гина оливкового масла,","10":"а возлияние – полгина вина. Это будет дар Господу, благоуханный дым, приятный Ему.","11":"Так должны вы поступать всякий раз, когда приносите в жертву быка или барана, ягненка или козленка.","12":"Сколько животных вы принесли в жертву, столько должно быть хлебных приношений и возлияний.","13":"Каждый коренной житель страны должен исполнять все это, когда приносит дар Господу, когда возносит благоуханный дым, приятный Ему.","14":"А если переселенец или кто бы то ни было еще, живущий среди вас или среди ваших потомков, захочет принести дар Господу, вознести благоуханный дым, приятный Ему, то он должен сделать все так же, как делаете вы.","15":"Пусть в общине будет одно правило и для вас, и для переселенцев. Это вам предписание навеки, соблюдайте его из рода в род. Переселенец пусть поступает пред Господом так же, как и вы.","16":"Одно правило и один закон – и для вас, и для живущих среди вас переселенцев».","17":"Господь сказал Моисею:","18":"«Передай сынам Израилевым: когда вы придете в землю, в которую Я веду вас,","19":"и станете есть хлеб той земли, делайте подношение Господу.","20":"Подносите в дар Господу лепешку первой выпечки из муки нового урожая – делайте это как подношение с гумна.","21":"Из рода в род должны вы из первой выпечки делать подношение Господу.","22":"Если вы по ошибке не выполнили какое-то из повелений, которые Господь возвестил Моисею, –","23":"что-то из того, что Он повелел вам через Моисея, – то вот как вам надлежит поступать (начиная с того самого дня, когда Господь дал вам это повеление, и впредь, из рода в род).","24":"Если ошибка была совершена по недосмотру общины, пусть вся община принесет в жертву быка – как всесожжение, как благоуханный дым, приятный Господу, с положенным хлебным приношением и возлиянием, и козла – как очистительную жертву.","25":"Пусть священник совершит искупительный обряд за всю общину сынов Израилевых, и они будут прощены. Ибо это была ошибка, и за эту ошибку они сделали приношение, дар Господу, и принесли очистительную жертву пред Господом.","26":"Вся община сынов Израилевых и переселенцы, живущие среди них, будут прощены, ибо весь народ совершил проступок по недосмотру.","27":"Если один человек совершит проступок по ошибке, он должен принести в жертву годовалую козу – как очистительную жертву.","28":"Пусть священник совершит пред Господом искупительный обряд за этого человека, совершившего проступок по ошибке. Он совершит за него искупительный обряд – и этот человек будет прощен.","29":"У вас должно быть одно правило для всякого, кто совершит проступок по ошибке, – и для коренного жителя из сынов Израилевых, и для переселенца, живущего среди них.","30":"Но если человек – будь то коренной житель или переселенец – совершил грех умышленно, то это оскорбление Господу; он будет отторгнут от рода своего.","31":"Он пренебрег словом Господа, он нарушил Его повеление – и будет отторгнут от рода своего; он понесет наказание за свой грех».","32":"Когда сыны Израилевы были в пустыне, то заметили, что один человек собирает дрова в субботу.","33":"Те, кто застиг его собирающим дрова, привели его к Моисею, Аарону и всей общине.","34":"Его посадили под стражу, потому что не было правила, которое говорило бы, как с ним поступить.","35":"Господь сказал Моисею: «Этот человек должен быть предан смерти. Пусть вся община забросает его камнями вне стана».","36":"Всей общиной его вывели из стана и насмерть забросали камнями. Так повелел Господь Моисею.","37":"Господь сказал Моисею:","38":"«Передай сынам Израилевым: пусть из рода в род они делают кисти по краям своей одежды, и в эти кисти вы должны вставлять голубую нитку.","39":"Глядя на эти кисти, вы должны вспоминать все повеления Господа и исполнять их, а не подчиняться своему сердцу и очам, которые влекут вас к разврату!","40":"Вы будете помнить и исполнять все Мои повеления и будете святыми у Бога вашего!","41":"Я – Господь, ваш Бог, который вывел вас из Египта, чтобы быть вашим Богом. Я – Господь, ваш Бог»."},"16":{"1":"Корей, сын Ицхара, сына Кехата, сына Левия, а также потомки Рувима – Датан и Авирам, сыновья Элиава, и Он, сын Пелета – взбунтовались против Моисея. Их поддержали двести пятьдесят сынов Израилевых; все это были вожди общины, предводители собрания, именитые люди.","3":"Они обступили Моисея и Аарона и сказали им: «Довольно вам! В общине все святые, и среди них пребывает Господь. Почему вы ставите себя над общиной Господней?»","4":"Услышав эти слова, Моисей пал ниц. Юн сказал Корею и его сообщникам: «Утром Господь покажет, кто принадлежит Ему, и кто свят, и кому Он позволяет приблизиться к Себе! Кого Он избрал, тому Он и позволит к Себе приблизиться.","6":"Возьмите кадильницы,","7":"положите в них горящие угли и благовония и предстаньте пред Господом. Кого Господь изберет, тот и свят. Довольно вам, сыны Левия!»","8":"«Послушайте, сыны Левия! – сказал Моисей Корею. –","9":"Неужели мало вам того, что Бог Израиля дал вам особое место в общине сынов Израилевых, позволил приближаться к Нему, выполнять работу при скинии Господней и прислуживать общине?","10":"Господь позволил тебе и твоим собратьям, левитам, приближаться к Нему, – а вы стали домогаться священничества!","11":"Ты и твои сообщники – вы против Господа устроили заговор! Аарон тут ни при чем – зачем вам роптать на него?»","12":"Моисей послал за Датаном и Авирамом, сыновьями Элиава, но они сказали: «Мы не придем!","13":"Мало тебе, что ты увел нас из земли, источающей молоко и мед, чтобы мы умерли в пустыне! Ты еще хочешь быть нашим владыкой?","14":"В землю, источающую молоко и мед, ты нас не привел, полей и виноградников нам не дал. Думаешь, люди слепы? Мы не придем к тебе!»","15":"Сильно разгневался Моисей и сказал Господу: «Да не будут угодны Тебе их приношения! Ведь я ни у кого из них даже осла не отнял, я никому из них зла не делал!»","16":"Моисей сказал Корею: «Завтра ты и все твои сообщники должны предстать пред Господом – и ты, и твои сообщники и Аарон.","17":"Пусть каждый из вас возьмет свою кадильницу, положит в нее благовония и принесет ее пред лицо Господа; принесите двести пятьдесят кадильниц, и ты принеси свою кадильницу, и Аарон свою».","18":"И все они взяли свои кадильницы, положили в них горящие угли и благовония и стали у входа в Шатер Встречи, вместе с Моисеем и Аароном.","19":"Корей собрал всю общину против Моисея и Аарона, они стояли у входа в Шатер Встречи. И тогда всей общине явилась слава Господня.","20":"Господь сказал Моисею и Аарону:","21":"«Отойдите от этой общины, и Я уничтожу их всех в одно мгновенье!»","22":"Но Моисей и Аарон пали ниц и сказали: «О Боже, Бог, дающий дыхание всему живому! Согрешил один человек, а Ты разгневался на всю общину?»","23":"Господь сказал Моисею:","24":"«Вели всей общине отойти подальше от жилищ Корея, Датана и Авирама».","25":"Моисей направился к жилищам Датана и Авирама – старейшины Израиля шли за ним –","26":"и сказал общине: «Отойдите от шатров этих негодных людей и к их вещам не прикасайтесь, а иначе и вы погибнете за все их грехи».","27":"Люди отошли подальше от жилищ Корея, Датана и Авирама. А Датан и Авирам остались стоять у входа в свои шатры, вместе с женами, детьми и младенцами.","28":"Моисей сказал: «Сейчас вы узнаете, что это Господь послал меня делать то, что я делаю; поймете, что это не моя прихоть.","29":"Если они умрут так, как все люди умирают, если их постигнет та же участь, что и всех, – значит не Господь меня к вам послал.","30":"Но если Господь сделает так, что земля раскроет свой зев и поглотит их самих и все, что им принадлежит, если они живыми сойдут в Шеол – тогда вы уразумеете, что эти люди отвергли Господа!»","31":"Только он умолк, как разверзлась земля под этими людьми:","32":"раскрыла свой зев и поглотила их вместе со всем, что было у них, – поглотила всех людей Корея и все их имущество!","33":"Живыми сошли они в Шеол, вместе со всем своим достоянием; и сомкнулась над ними земля, и не стало их среди собравшихся.","34":"Услышав их крики все стоявшие вокруг бросились бежать – они боялись, что земля и их поглотит.","35":"Сошел огонь от Господа и уничтожил двести пятьдесят человек, которые принесли благовония в кадильницах.","36":"Господь сказал Моисею:","37":"«Вели Элеазару, сыну священника Аарона, собрать на пепелище все кадильницы, выкинув из них угли.","38":"Теперь они освящены ценой жизни этих грешников. Пусть из этих кадильниц выкуют листы для покрытия жертвенника. Их приносили к Господу, и они стали священными – да будут они знамением для сынов Израилевых!»","39":"Священник Элеазар собрал медные кадильницы, принесенные погибшими в огне, – и из них выковали покрытие для жертвенника,","40":"как и велел Элеазару Господь через Моисея. Это покрытие призвано напоминать сынам Израилевым, что никто из посторонних, никто, кроме потомков Аарона, не должен совершать воскурение благовоний пред Господом – иначе он разделит участь Корея и его сообщников.","41":"На следующий день вся община сынов Израилевых возмутилась против Моисея и Аарона и стала их обвинять: «Вы убивали народ Господень!»","42":"Когда вся община собралась против Моисея и Аарона, они посмотрели в сторону Шатра Встречи и увидели: облако скрыло Шатер, явилась слава Господня.","43":"Моисей и Аарон подошли к Шатру Встречи","44":"и Господь сказал Моисею:","45":"«Отойдите от этой общины, и Я уничтожу их всех в одно мгновенье!» Оба пали ниц.","46":"Моисей сказал Аарону: «Возьми свою кадильницу, положи в нее горящие угли с жертвенника, положи благовония и спеши к общине, соверши за них искупительный обряд. Пришел гнев от Господа: начался мор!»","47":"Аарон сделал, как велел ему Моисей, и побежал к общине – а мор уже начался. Аарон положил на угли благовония и совершил искупительный обряд за народ.","48":"Встал он меж мертвыми и живыми – и мор прекратился.","49":"А погибло от мора четырнадцать тысяч семьсот человек, не считая тех, кто погиб вместе с Кореем.","50":"Аарон вернулся к Моисею, ко входу в Шатер Встречи. Мор прекратился."},"17":{"1":"Господь сказал Моисею:","2":"«Вели сынам Израилевым принести тебе двенадцать посохов, по одному от каждого племени – посохи вождей племен. На каждом посохе напиши имя его хозяина,","3":"на посохе от племени Левия напиши имя Аарона. От каждого предводителя рода – по посоху.","4":"Положи посохи в Шатре Встречи, пред Заветом, там, где Я встречаюсь с вами.","5":"Посох человека, которого Я изберу, зазеленеет – Я сделаю так, чтобы Мне больше не слышать, как ропщут на вас сыны Израилевы».","6":"Моисей передал это сынам Израилевым, и их вожди принесли ему свои посохи, по одному посоху от каждого вождя – всего двенадцать посохов, и еще посох Аарона.","7":"Моисей положил эти посохи пред Господом, в Шатре Завета.","8":"На следующий день Моисей вошел в Шатер Завета и увидел, что посох Аарона – посох племени Левия – зазеленел: на нем появились почки, распустились цветки и созрел миндаль.","9":"Моисей взял все посохи, лежавшие пред Господом, и вынес их к сынам Израилевым. Те увидели свои посохи и разобрали их.","10":"Господь сказал Моисею: «Положи посох Аарона пред Заветом, пусть хранится там как знамение для строптивых людей. Так ты положишь конец их ропоту – и они не погибнут».","11":"Моисей сделал все в точности так, как повелел ему Господь.","12":"Сыны Израилевы сказали Моисею: «Нам конец, мы погибли, все мы погибли!","13":"Всякий, кто приблизится к скинии Господней, умрет! Неужели нам всем пришел конец?»"},"18":{"1":"Господь сказал Аарону: «Ты и твои потомки, а также весь твой род – вы будете отвечать за то, чтобы грех не запятнал святилище. Ты и твои потомки – вы будете отвечать за то, чтобы грех не запятнал священническое служение.","2":"Призови своих собратьев из племени Левия, из твоего родного племени, чтобы они были с тобой и помогали тебе, когда ты со своими сыновьями служишь пред Шатром Завета.","3":"Пусть они помогают тебе и выполняют работу для Шатра, но они не должны приближаться к священной утвари и к жертвеннику, иначе и они погибнут, и вы вместе с ними.","4":"Пусть они вместе с тобой отвечают за Шатер Встречи, пусть делают всю работу. Но никто посторонний пусть не приближается к вам –","5":"всю работу для святилища и жертвенника выполняете вы – иначе Гнев снова падет на сынов Израилевых.","6":"Я забираю ваших собратьев, левитов, у сынов Израилевых и отдаю их вам, это Мой дар вам; они отданы Господу, чтобы работать при Шатре Встречи.","7":"Ты же и потомки твои должны исполнять свое священническое служение у жертвенника и за завесой. Я даю вам священническое служение как дар; если приблизится посторонний, его следует предать смерти».","8":"Господь сказал Аарону: «Я отдаю в твое распоряжение все подношения, сделанные Мне, все священные приношения сынов Израилевых. Я отдаю их тебе и твоим потомкам как долю, которая причитается вам вовеки.","9":"Тебе принадлежит святыня святынь – часть жертв, принесенных Мне в дар. Часть всех приношений, которые принесены Мне сынами Израилевыми, всех их хлебных, очистительных и возместительных жертв – святыня святынь – принадлежит тебе и твоим потомкам.","10":"Ешь ее как святыню святынь; только мужчина может есть ее; да будет она для тебя святыней.","11":"Твоими будут все подношения сынов Израилевых, все, что они возносят как дар. Я отдаю это тебе, сыновьям и дочерям твоим как долю, причитающуюся вам вовеки. Каждый член твоей семьи, который чист, может есть это.","12":"Лучшее масло, лучшее вино и зерно – первинки нового урожая, принесенные Господу, – Я отдаю тебе.","13":"Все первые плоды урожая, принесенные Господу, принадлежат тебе. Каждый член твоей семьи, если он чист, может их есть.","14":"Все, что предано заклятью в Израиле, принадлежит тебе.","15":"Первый плод всякого материнского чрева, и у людей, и у скота, – то, что приносится Господу, – принадлежит тебе. Но человеческие первенцы должны быть выкуплены, и первенцы нечистых животных должны быть выкуплены.","16":"За ребенка, достигшего месячного возраста, бери выкуп – пять шекелей серебра, в шекелях святилища (в шекеле – двадцать гер).","17":"Но первенец коровы, овцы или козы выкупу не подлежит – это святыня. Его кровью ты должен окропить жертвенник, а его жир сожги – это дар Господу, благоуханный дым, приятный Ему.","18":"При этом мясо достается тебе – так же, как достается тебе грудь жертвы, возносимая как дар, и правое бедро жертвы.","19":"Все священные подношения, которые сыны Израилевы подносят Господу, Я отдаю тебе, сыновьям и дочерям твоим как долю, причитающуюся вам вовеки. Это вечный договор, солью хранимый; договор, заключенный пред Господом с тобой и с твоими потомками».","20":"Господь сказал Аарону: «Ты не получишь надела на земле сынов Израилевых, не будешь иметь доли среди них. Твоя доля и твой надел среди сынов Израилевых – это Я.","21":"Вместо земельного надела Я отдаю потомкам Левия все десятины в Израиле – за ту работу, которую они выполняют при Шатре Встречи.","22":"А сыны Израилевы не должны приближаться к Шатру Встречи; если приблизятся – согрешат и поплатятся за это жизнью.","23":"Только левиты должны выполнять работу при Шатре Встречи, и они отвечают за то, чтобы грех не запятнал его. Это вам предписание навеки, соблюдайте его из рода в род. У левитов не будет земельного надела среди сынов Израилевых.","24":"Вместо надела Я отдал левитам десятины, которые сыны Израилевы приносят в дар Господу, – а потому говорю левитам, что у них не будет земельного надела среди сынов Израилевых».","25":"Господь сказал Моисею:","26":"«Скажи левитам: когда вы получите от сынов Израилевых десятину, которую Я дал вам вместо земельного надела, то отделите от нее подношение Господу – десятину от десятины.","27":"Это будет считаться вашим подношением – как зерно с гумна или виноградное сусло из давильни.","28":"Делайте такое подношение Господу от всех десятин, которые вы собираете с сынов Израилевых; это подношение Господу вы должны передавать священнику Аарону.","29":"От всего, что вам приносят, отделяйте подношение Господу, из самой лучшей части – священную часть.","30":"Скажи левитам: когда вы отделите от десятины лучшую часть, то остальное будет для вас все равно что приношение с гумна или из давильни.","31":"Это ваше вознаграждение за работу при Шатре Встречи. И вы, и ваши семьи можете есть его на любом месте,","32":"и это не будет вменено вам в вину. Поскольку вы уже отделили от десятины лучшую часть, то вы не оскверните святые приношения сынов Израилевых и не поплатитесь за это жизнью»."},"19":{"1":"Господь сказал Моисею и Аарону:","2":"«Вот правило, предписанное Господом. Вели сынам Израилевым привести к тебе рыжую корову, без изъянов и недостатков, никогда не бывшую под ярмом.","3":"Передайте ее священнику Элеазару; пусть ее выведут за пределы стана и зарежут у него на глазах,","4":"а священник Элеазар пусть возьмет кровь коровы на палец и семь раз покропит этой кровью в сторону Шатра Встречи.","5":"Корову надо сжечь у него на глазах – сжечь ее шкуру, мясо, кровь и нечистоты.","6":"Пусть священник возьмет кусок кедрового дерева, иссоп и лоскут багряной ткани и бросит в огонь, в котором горит тело коровы.","7":"Затем священник должен постирать свою одежду и совершить омовение. После этого он может вернуться в стан, но останется нечистым до вечера.","8":"Человек, сжигавший корову, также должен постирать свою одежду и совершить омовение; он останется нечистым до вечера.","9":"Кто-нибудь, кто чист, должен собрать пепел коровы и перенести его на чистое место за пределами стана. Этот пепел должен храниться, чтобы община сынов Израилевых могла готовить воду очищения. Это очистительная жертва.","10":"Тот, кто собирал пепел коровы, должен постирать свою одежду; он останется нечистым до вечера. Это – предписание навеки, и для сынов Израилевых, и для живущих среди них переселенцев.","11":"Тот, кто прикоснулся к умершему человеку, будет нечистым семь дней.","12":"На третий день и на седьмой день он должен пройти очищение этим пеплом – и будет чист. А если он не прошел очищение на третий и на седьмой день, то не станет чистым.","13":"Тот, кто прикоснулся к умершему и не очистился, оскверняет скинию Господа – такой человек будет отторгнут от Израиля. Он не был окроплен водой очищения и остается нечистым; нечистота его пребывает на нем.","14":"Вот закон. Если в шатре умер человек, то всякий, кто войдет в шатер, и всякий, кто находится в шатре, будет нечистым семь дней.","15":"Всякий открытый сосуд – сосуд, который не закрыт плотно, – станет нечистым.","16":"Всякий, кто на открытом месте прикоснется к убитому, умершему, к костям мертвеца или к могиле, будет нечист семь дней.","17":"Чтобы его очистить, надо взять пепел той сожженной очистительной жертвы и смешать его в сосуде с проточной водой.","18":"Пусть кто-нибудь, кто чист, возьмет иссоп, окунет его в эту воду и окропит шатер, все вещи и людей в шатре, или того человека, который прикоснулся к костям, к убитому, к умершему или к могиле.","19":"Чистый человек должен окропить нечистого на третий день, а потом на седьмой день – тем самым, на седьмой день, он очистит его от нечистоты. Тот должен постирать свою одежду и совершить омовение – и вечером будет чист.","20":"А кто стал нечистым и не очистился, тот будет отторгнут от общины. Он оскверняет святилище Господа: он не был окроплен водой очищения – он нечист.","21":"Это им предписание навеки. Тот, кто окроплял водой очищения, должен постирать свою одежду. Всякий, кто прикоснется к воде очищения, останется нечистым до вечера.","22":"Все, к чему прикоснется нечистый человек, становится нечистым; тот, кто прикоснется к нему, будет нечистым до вечера»."},"20":{"1":"… И вот, в новолуние первого месяца вся община сынов Израилевых достигла пустыни Цин. Сыны Израилевы остановились в Кадеше. Там умерла Мирьям, и там ее похоронили.","2":"Общине не хватало воды, люди столпились вокруг Моисея и Аарона","3":"и стали упрекать Моисея: «Уж лучше бы нам было погибнуть пред лицом Господа, как наши братья!","4":"Зачем вы с Аароном привели общину Господню в эту пустыню? Чтобы и мы, и наш скот умерли здесь?","5":"Зачем вы увели нас из Египта в эти проклятые места, где нельзя сеять, где нет ни смокв, ни винограда, ни гранатов? Даже воды нет для питья!»","6":"Моисей и Аарон, оставив собравшихся, пришли ко входу в Шатер Встречи и пали ниц. Тогда явилась им слава Господня","7":"и Господь сказал Моисею:","8":"«Возьми этот посох и, вместе с братом твоим Аароном, собери всю общину. Затем, на глазах у всех, повелите скале дать воду. Ты добудешь для них воду из скалы и напоишь всю общину и скот».","9":"Моисей, как велел ему Господь, взял посох, лежавший пред лицом Господа.","10":"Моисей и Аарон собрали народ у скалы, и Моисей сказал: «Слушайте, бунтовщики! Неужели мы должны добыть для вас воду из этой скалы?»","11":"Моисей дважды ударил своим посохом по скале, и из скалы потекла вода – так много, что хватило и всей общине, и скоту.","12":"Господь сказал Моисею и Аарону: «За то, что вы не поверили Мне и не явили святость Мою пред сынами Израилевыми, вам не дано будет привести этот народ в страну, которую Я им отдаю».","13":"Этот источник – это воды Меривы; там сыны Израилевы обвиняли Господа, а Он явил им Свою святость.","14":"Из Кадеша Моисей отправил послов, передать царю Эдома: «Так говорит твой брат Израиль: ты знаешь, какие тяготы выпали на нашу долю.","15":"Предки наши пришли в Египет, и мы долгое время жили в Египте. Египтяне угнетали нас, как и отцов наших.","16":"Когда мы воззвали к Господу, Он услышал нас и послал ангела, который вывел нас из Египта. Сейчас мы в селении Кадеш, у границы твоих владений.","17":"Разреши нам пройти по твоей земле! Мы не пойдем через посевы и виноградники, не станем пить воду из колодцев. Мы двинемся по Царской дороге – и не свернем ни вправо, ни влево, пока не минуем твои владения».","18":"Эдомитяне ответили: «Вы не пройдете по нашей земле! А попробуете – мы выйдем вам навстречу с мечами в руках!»","19":"Сыны Израилевы сказали: «Мы пойдем по дороге. Если будем пить вашу воду или поить ею наш скот, мы вам заплатим. Нам ничего не нужно – только пройти мимо!»","20":"Но те ответили: «Вы не пройдете по нашей земле!» И, собрав большое и сильное войско, они вышли навстречу сынам Израилевым.","21":"Так эдомитяне не пропустили сынов Израилевых через свои владения. Сыны Израилевы пошли в другую сторону.","22":"Покинув Кадеш, община сынов Израилевых пришла к горе Ор.","23":"Там, у горы Ор, близ границы Эдома, Господь сказал Моисею и Аарону:","24":"«Аарон должен отойти к предкам своим. Вы ослушались Меня у источника Мерива, и за это Аарон не войдет в страну, которую Я отдаю сынам Израилевым.","25":"Приведи Аарона и сына его Элеазара на гору Ор.","26":"Сними с Аарона его одежды и облеки в них его сына Элеазара. Там Аарон умрет, отойдет к предкам своим».","27":"Моисей сделал так, как повелел Господь. На глазах у всей общины они поднялись на гору Ор,","28":"и там Моисей снял с Аарона его одежды и облек в них его сына Элеазара. И умер Аарон там, на вершине горы, а Моисей и Элеазар спустились вниз.","29":"Узнала вся община, что умер Аарон – и оплакивали его все сыны Израилевы тридцать дней."},"21":{"1":"Царь Арада, ханааней, правивший Негевом, узнал, что сыны Израилевы идут по дороге на Атарим. Он напал на них и захватил пленных.","2":"Тогда сыны Израилевы дали Господу обет: если Господь дарует им победу над этим народом, то они предадут заклятию и уничтожат все селения побежденных.","3":"Господь внял этому обету и даровал сынам Израилевым победу над ханаанеями. Они предали заклятью и уничтожили ханаанеев со всеми их селениями. Это место получило название Хорма .","4":"От горы Ор сыны Израилевы пошли по дороге, ведущей к морю Суф, в обход Эдома. В пути люди совсем потеряли терпение,","5":"стали роптать на Бога и Моисея: «Зачем вы увели нас из Египта? Чтобы мы умерли в пустыне? Здесь нет еды, нет воды! А эта негодная еда нам уже опротивела!»","6":"Господь наслал на них ядовитых змей, которые жалили их, и многие из сынов Израилевых погибли.","7":"Тогда люди пришли к Моисею и сказали: «Согрешили мы, когда роптали на Господа и на тебя. Помолись Господу, пусть Он избавит нас от змей!» Моисей помолился за народ,","8":"и Господь сказал Моисею: «Сделай изображение змея и подними его как боевой значок на древке. Пусть всякий, кого ужалит змея, посмотрит на него – и тогда он останется жив».","9":"Моисей сделал змея из меди и поднял его как боевой значок на древке. И всякий, кого ужалила змея, глядел на этого медного змея – и оставался жив.","10":"Сыны Израилевы двинулись в путь, затем сделали остановку в Овоте.","11":"После Овота они сделали остановку в Ийе–ха – Аварим, в пустыне, которая лежит к востоку от Моава.","12":"Следующую остановку они сделали в ущелье Зеред.","13":"После этого они перешли ущелье Арнон и остановились в пустыне, которая прилегает к владениям амореев. (Арнон – граница Моава, граница между Моавом и владениями амореев.","14":"Потому-то и сказано в Книге войн Господних: «… и Вахев, что в Суфе, и ущелья, и Арнон,","15":"и склоны ущелий, которые спускаются к селению Ар и достигают границ Моава».)","16":"Оттуда они пришли в Беэр. Там находится тот самый колодец, о котором Господь сказал Моисею: «Собери народ, и Я дам им воду».","17":"Там сыны Израилевы воспели песнь: «Наполнись, колодец! О колодце пойте!","18":"Копали его вожди, предводители народа копали – посохами, жезлами своими». Из той пустыни они пришли в Маттану ,","19":"из Маттаны – в Нахалиэл, из Нахалиэла – в Бамот,","20":"а из Бамота – в долину, что на моавских землях, близ горы Фасга, которая высится над пустыней.","21":"Сыны Израилевы отправили послов к Сихону, аморейскому царю, с просьбой:","22":"«Разреши нам пройти по твоей земле! Мы не пойдем через посевы и виноградники, не станем пить воду из колодцев. Мы будем идти по Царской дороге, пока не минуем твои владения».","23":"Но Сихон не позволил сынам Израилевым пройти через его владения. Он собрал все свое войско, вышел в пустыню им навстречу и сразился с ними у Яхаца.","24":"Сыны Израилевы разбили Сихона. Они овладели всей его страной, от Арнона до Яббока – до земли сынов Аммоновых (владения сынов Аммоновых были хорошо защищены).","25":"Сыны Израилевы захватили и заселили все города амореев, включая Хешбон с окрестными селениями.","26":"Хешбон – это город Сихона, аморейского царя. Воюя с прежним царем Моава, Сихон отобрал у него все земли вплоть до Арнона.","27":"Потому и говорят сказители: «Приходите в Хешбон! Да будет отстроен и укреплен город Сихона!","28":"Огонь из Хешбона вышел, вышло пламя из Сихонова града, уничтожив и Ар в Моаве, и владык Бамота над Арноном.","29":"Горе тебе, Моав! Ты погиб, народ Кемоша! Сыны его беженцами стали, дочери попали в неволю к Сихону, царю амореев.","30":"Мы их засыпали стрелами! Погибло все от Хешбона до Дивона! Мы разорили все до Нофаха, до Медевы».","31":"Так сыны Израилевы поселились в стране амореев.","32":"Затем Моисей послал людей осмотреть Язер. Сыны Израилевы захватили селения вокруг Язера, и стали жить на месте обитавших там прежде амореев.","33":"Оттуда, повернув, сыны Израилевы пошли по дороге, ведущей в Башан. Ог, царь башанский, вышел им навстречу со всем своим войском и вступил с ними в бой у Эдреи.","34":"Господь сказал Моисею: «Не бойся. Я отдаю в твои руки и его самого, и все его войско, и его страну. Ты поступишь с ним так же, как с Сихоном, аморейским царем, правившим в Хешбоне».","35":"Перебив их всех – и Ога, и сыновей его, и все его войско, до последнего человека, Сыны Израилевы овладели и этой страной."},"22":{"1":"Оттуда сыны Израилевы двинулись дальше и остановились на Моавской равнине, за Иорданом, близ Иерихона.","2":"Балак, сын Циппора, видел, что сделали сыны Израилевы с амореями.","3":"Весь Моав был охвачен ужасом перед ними – так они были многочисленны. Страхом и ненавистью к сынам Израилевым был охвачен Моав,","4":"и моавитяне сказали старейшинам Мидьяна: «Эта орда все вокруг нас смела дочиста – словно бык траву полевую»! Балак, сын Циппора, который был в ту пору царем Моава,","5":"отправил послов к Валааму, сыну Беора, в Петор (что находится на Реке, в стране сынов Аммоновых) и позвал Валаама на помощь. Он говорил: «Пришел народ из Египта, и всю землю заполонил, и поселился рядом со мною.","6":"Приди и выполни мою просьбу: прокляни этот народ. Сейчас они сильнее меня – а тогда, быть может, я смогу их разбить и выгнать вон из страны. Я ведь знаю: кого ты благословишь, тот благословен, а кого ты проклянешь, тот проклят».","7":"Старейшины Моава и старейшины Мидьяна пришли к Валааму, принесли плату за чародейство и передали ему слова Балака.","8":"Валаам сказал: «Останьтесь здесь на ночь, и я отвечу вам, что мне скажет Господь». Моавские вельможи остались ночевать у Валаама.","9":"Бог пришел к Валааму и сказал: «Что это за люди здесь с тобой?»","10":"Валаам сказал Богу: «Балак, сын Циппора, царь Моава, велел им передать мне:","11":"народ пришедший из Египта заполонил всю землю. Приди и выполни мою просьбу: нашли на него проклятье. Быть может, я смогу сразиться с ним и выгнать его вон».","12":"Бог ответил Валааму: «Не ходи с ними. Ты не проклянешь этот народ, ибо на нем благословение».","13":"Наутро Валаам сказал послам Балака: «Возвращайтесь к себе. Господь не позволяет мне идти с вами».","14":"Встали моавские вельможи, вернулись к Балаку и сказали: «Валаам отказался идти с нами».","15":"Снова Балак отправил послов – еще более знатных и почтенных, чем в первый раз.","16":"Они пришли к Валааму и сказали: «Так говорит Балак, сын Циппора: не откажись придти ко мне.","17":"Я окажу тебе великие почести, выполню все, что ты мне скажешь. Только приди и выполни мою просьбу: нашли на этот народ проклятие».","18":"Валаам ответил вельможам Балака: «Даже если бы Балак сулил мне весь свой дворец, полный серебра и золота, – все равно, ни в каком деле, ни малом, ни великом, не смог бы я преступить повелений Господа, Бога моего.","19":"Но останьтесь и вы здесь на ночь – я посмотрю, что еще скажет мне Господь».","20":"Ночью Бог пришел к Валааму и сказал: «Раз эти люди пришли к тебе и позвали тебя – иди с ними. Но делай только то, что Я тебе скажу».","21":"Наутро Валаам встал, оседлал свою ослицу и вместе с моавскими вельможами пустился в путь.","22":"Разгневался Бог, что Валаам пустился в путь, – и ангел Господа преградил ему дорогу. А Валаам ехал на ослице, и с ним было двое слуг.","23":"Увидела ослица, что ангел Господа с обнаженным мечом в руке стоит на дороге – и свернула с дороги в поле. Валаам принялся бить ослицу, чтобы вернуть ее обратно на дорогу.","24":"Ангел Господа встал там, где дорога сужалась между двумя виноградниками – по одну сторону там была стена и по другую сторону стена.","25":"Увидела ослица ангела Господня и прижалась к стене, прижав к стене ногу Валаама. Он опять принялся бить ее.","26":"Ангел Господа чуть отошел и встал в таком узком месте, где уже нельзя было свернуть ни вправо, ни влево.","27":"Увидела ослица ангела Господня и опустилась под Валаамом на землю. Гнев охватил Валаама и он стал бить ослицу палкой.","28":"И отверз тогда Господь уста ослицы – она сказала Валааму: «Что я сделала тебе, что ты уже третий раз принимаешься бить меня?» –","29":"«Ты издеваешься надо мной! – ответил Валаам. – Был бы у меня меч, я убил бы тебя».","30":"Ослица спросила Валаама: «Разве я не твоя ослица, на которой ты ездил всю жизнь? И что – была у меня привычка так вести себя с тобой?» – «Нет», – ответил Валаам.","31":"И отверз тогда Бог очи Валаама – увидел Валаам ангела Господнего, стоящего на дороге с обнаженным мечом в руке. Склонился Валаам до земли и пал ниц.","32":"Ангел Господа спросил его: «Так за что ты три раза бил ослицу? Это я вышел навстречу тебе, чтобы остановить тебя, – и мимо меня не пройти.","33":"Ослица видела меня и три раза поворачивала в сторону передо мною. Если бы она не поворачивала, то ее-то я пощадил бы – а тебя убил!»","34":"И сказал Валаам ангелу Господа: «Виноват я! Не знал я, что это ты стоишь у меня на пути. Если неугодно тебе то, что я делаю, – я готов вернуться».","35":"Ангел Господа ответил Валааму: «Иди с этими людьми. Но говори лишь то, что я тебе скажу». И Валаам пустился в путь с вельможами Балака.","36":"Балаку сказали, что идет Валаам, и Балак пошел встречать его в Ир – Моаве, что на границе, у Арнона, на самых дальних рубежах той страны.","37":"«Я посылал за тобой, – сказал Балак Валааму, – что же ты не шел? Неужели я не могу почтить тебя, как подобает?»","38":"Валаам ответил Балаку: «Вот я пришел. Но что я могу сказать? Что Бог вложит в мои уста, то я и скажу».","39":"И пошел Валаам с Балаком в Кирьят – Хуцот.","40":"Балак велел зарезать быков и овец и позвал Валаама, а также вельмож, что сопровождали его.","41":"А на следующее утро Балак отвел Валаама в Бамот – Баал; и оттуда Валаам увидел небольшую часть израильского стана."},"23":{"1":"Валаам сказал Балаку: «Воздвигни здесь для меня семь жертвенников, приготовь для жертвоприношения семь быков и семь баранов».","2":"Балак сделал, как сказал ему Валаам. На каждом жертвеннике Балак и Валаам принесли в жертву по быку и по барану,","3":"и Валаам сказал Балаку: «Стой рядом с принесенными тобой жертвами всесожжения. А я отойду и, быть может, Господь выйдет мне навстречу. Что Он откроет мне, то я и возвещу тебе». Он отошел на голый холм,","4":"и там встретил его Бог. Валаам сказал ему: «Семь жертвенников я воздвиг, на каждом принес в жертву по быку и по барану».","5":"И Господь вложил слова в уста Валаама. «Возвращайся к Балаку и возвести ему это», – сказал он Валааму.","6":"Валаам вернулся к Балаку – тот, вместе со всеми вельможами Моава, стоял возле принесенных им жертв всесожжения.","7":"И возвестил Валаам слово свое: «Из страны арамеев привел меня Балак, царь Моава привел меня с восточных гор: „Приди, по просьбе моей прокляни Иакова; приди и наведи проклятье на Израиль\".","8":"Как могу я проклясть? Не проклинает его Бог! Как проклятье наведу? Господь проклятье не наводит!","9":"Со скалистых вершин я вижу его, с холмов я на него смотрю: вижу народ, что живет, не тревожимый никем, не причисляет себя к числу народов.","10":"Людей Иакова считать – все равно, что песок. Израильтян пересчитывать – все равно, что пыль. Кончиной праведника да будет кончина моя: мое потомство да будет таким, как этот народ!»","11":"«Что ты делаешь со мной? – спросил Балак Валаама. – Я позвал тебя проклясть моих врагов, а ты благословляешь их».","12":"Валаам ответил: «Что Господь вложил в мои уста, то я и должен сказать, в точности».","13":"Балак сказал: «Пойдем со мной в другое место. Оттуда ты увидишь их – но только самый край их стана, а не всех. Прокляни их оттуда, выполни мою просьбу».","14":"Он повел его на Поле Дозорных, что у вершины Фасги, построил там семь жертвенников и на каждом принес в жертву по быку и по барану.","15":"Валаам сказал Балаку: «Стой здесь, рядом с принесенными тобой жертвами всесожжения. А я пойду туда, на встречу к Нему».","16":"И встретил Господь Валаама, и вложил слова в его уста. «Возвращайся к Балаку и возвести ему это», – сказал Он Валааму.","17":"Валаам вернулся к Балаку – тот стоял возле принесенных им жертв всесожжения, а рядом с ним стояли вельможи Моава. Балак спросил: «Что сказал Господь?»","18":"И возвестил Валаам слово свое: «Встань и слушай, Балак, внимай мне, Циппоров сын.","19":"Бог не человек – не солжет; не как люди Он – не передумает. Неужели скажет Он и не сделает? Пообещает и не выполнит?","20":"Я был избран, чтобы благословить: благословил Он – и не мне отменять!","21":"Нет, не видно у Иакова беды! У Израиля – несчастья не видно! С этим народом – его Бог, Господь, они приветствуют Его как Царя.","22":"У Бога, что их вывел из Египта, мощь – как рога дикого быка!","23":"Не сыскать против Иакова гаданья, предсказаний не сыскать против Израиля. Так говорят об Иакове – Израиле: „Смотри, что делает Бог!\"","24":"Словно лев встает этот народ, словно лев вздымается он, не успокоится, добычи не вкусив и не насытившись кровью убитых!»","25":"После этого Балак сказал Валааму: «Давай, ты не будешь ни проклинать их, ни благословлять!»","26":"Но Валаам ответил Балаку: «Разве я тебе не говорил, что буду делать все, что мне скажет Господь?»","27":"Балак сказал ему: «Я отведу тебя в другое место. Быть может, Богу будет угодно, чтобы ты выполнил мою просьбу и проклял их оттуда…»","28":"И Балак отвел Валаама на вершину Пебра, что возвышается над пустыней.","29":"Валаам сказал Балаку: «Воздвигни здесь для меня семь жертвенников, приготовь для жертвоприношения семь быков и семь баранов».","30":"Балак сделал, как сказал ему Валаам, и на каждом жертвеннике принес в жертву по быку и по барану."},"24":{"1":"А Валаам, увидев, что Господу угодно благословить Израиль, уже не пошел, как прежде, искать знамений. Он повернулся лицом к пустыне,","2":"и посмотрел, и увидел сынов Израилевых, расположившихся там племя за племенем. Тогда охватил его дух Божий","3":"и произнес он слово свое: «Говорит Валаам, сын Беоров, говорит тот, чье око отверсто,","4":"кто слышит слова Бога и виденья Всесильного зрит: он наземь пал, обнажено его око.","5":"Как прекрасны шатры твои, Иаков, и жилища твои, Израиль!","6":"Распростерты, как зелень в долинах, словно сады у реки, как алоэ, что Господь посадил, как кедры, что у ручья:","7":"влага капает с их ветвей, семя их – у многоводного потока. Их царь возвысится превыше Агага, великим будет царство его!","8":"У Бога, что их вывел из Египта, мощь – как рога дикого быка! Он пожирать будет враждебные народы, крушить их кости, ломать их стрелы.","9":"Словно лев он склонился, на землю лег – кто осмелится льва потревожить? Кто тебя благословит, благословен; а кто тебя проклянет, проклят».","10":"Разгневался Балак на Валаама, ударил рука об руку в негодовании и сказал: «Я позвал тебя проклясть моих врагов, а ты их благословляешь – вот уже третий раз!","11":"Убирайся, беги домой! Я думал было почтить и вознаградить тебя, но вот – Господь лишил тебя права получить эти почести».","12":"И ответил Валаам Балаку: «Разве я не предупреждал послов, которых ты присылал ко мне? Я говорил:","13":"„Даже если бы Балак сулил мне весь свой дворец, наполненный серебром и золотом, все равно не смог бы я преступить повелений Господа – ни добро сделать, ни зло сделать по собственному произволу. Что скажет Господь, то я и буду говорить\".","14":"Я возвращаюсь в свою страну. А ты подойди, и я тебе возвещу, что сделает в грядущем этот народ с твоим народом».","15":"И произнес он слово свое: «Говорит Валаам, сын Беоров, говорит тот, чье око отверсто,","16":"кто слышит слова Бога, кому открыто Всевышнего знанье, кто виденья Всесильного зрит: он наземь пал, обнажено его око.","17":"Я вижу то, чего еще нет, вижу то, что еще вдали! Вот восходит звезда из Иакова, жезл вздымается из Израиля, – раздробит он виски Моаву, разобьет темя всем сынам Шета.","18":"Завоеван будет Эдом, под пятой врагов будет Сеир, – а Израиль явит силу свою,","19":"а Иаков – их одолеет, добьет тех, кто остался в Ире!»","20":"Посмотрел Валаам на амалекитян и произнес слово свое: «Первый из народов Амалек, но ждет конец его – гибель навеки!»","21":"Посмотрел Валаам на каинитов и произнес слово свое: «Крепко жилище твое, и гнездо твое на скале;","22":"но в запустенье Каин придет, когда Ашшур поведет тебя в плен».","23":"И произнес Валаам слово свое: «О, кто останется в живых после содеянного Богом!","24":"Вот корабли из страны киттеев – покорят они Ашшур, покорят Заречье. Но и они погибнут навеки».","25":"И пошел Валаам к себе на родину, а Балак к себе."},"25":{"1":"Когда сыны Израилевы стояли в Шиттиме, народ стал развратничать с моавитянками,","2":"а те позвали их участвовать в жертвоприношениях своему богу. Народ ел жертвенное мясо и поклонялся их богу.","3":"Израиль стал поклоняться Ваалу Пеорскому – и разгорелся гнев Господа на Израиль.","4":"Господь сказал Моисею: «Возьми всех предводителей народа и распни их на солнце, чтобы умилостивить Господа. Тогда прекратится гнев Господа на Израиль».","5":"Моисей велел вождям Израиля: «Пусть каждый из вас сам убьет тех из своих людей, кому полюбился Ваал Пеорский!»","6":"В это время один из сынов Израилевых привел к своим родичам мидьянитянку – прямо на глазах у Моисея и всей общины сынов Израилевых, плакавших перед входом в Шатер Встречи.","7":"Увидев это, Пинехас, сын Элеазара, внук священника Аарона, покинул собрание общины, взял копье,","8":"проследовал за тем израильтянином в палатку – и там пронзил их обоих копьем, и израильтянина, и женщину, прямо в палатке. И мор среди сынов Израилевых тотчас прекратился.","9":"(А всего от мора погибло двадцать четыре тысячи человек.)","10":"Господь сказал Моисею:","11":"«Пинехас, сын Элеазара, сына священника Аарона, отвел Мой гнев от сынов Израилевых. Он отомстил за оскорбления, Мне нанесенные, и Я не уничтожил сынов Израилевых в ярости Своей.","12":"Объяви: Я заключаю с Пинехасом договор, несущий ему благоденствие,","13":"и по этому договору он и его потомки навеки получают священническое звание, – ибо Пинехас отомстил за оскорбления, нанесенные Богу его и искупил вину сынов Израилевых».","14":"Израильтянина, убитого вместе с мидьянитянкой, звали Зимри, сын Салу; он был главой одного из родов племени Симеона.","15":"А убитую мидьянитянку звали Козби, дочь Цура. Цур был предводителем одного из мидьянских родов.","16":"Господь сказал Моисею:","17":"«Будьте врагами мидьянитян, истребляйте их!","18":"Ведь и они поступают с вами как враги. Они вам подстроили и Пеорскую ловушку, и ловушку с Козби, дочерью мидьянского вождя, – их соплеменницей, убитой во время пеорского мора!»"},"26":{"1":"После того как мор закончился, Господь сказал Моисею и Элеазару, сыну священника Аарона:","2":"«Сделайте перепись всей общины сынов Израилевых, по родам, – всех от двадцати лет и старше, способных носить оружие».","3":"На Моавской равнине, у Иордана, напротив Иерихона, Моисей и священник Элеазар сделали перепись","4":"людей от двадцати лет и старше, – как и повелел Господь Моисею. Вот сыны Израилевы, ушедшие из Египта.","5":"Рувим, первенец Израиля. Потомки Рувима: от Еноха – род Еноха, от Паллу – род Паллу,","6":"от Хецрона – род Хецрона, от Карми – род Карми.","7":"Это роды потомков Рувима; в списки было внесено сорок три тысячи семьсот тридцать человек.","8":"Сын Паллу – Элиав.","9":"Сыновья Элиава: Немуэл, Датан и Авирам. (Это те самые Датан и Авирам, из числа самых уважаемых людей общины, которые вместе с Кореем и его сообщниками восстали против Моисея и Аарона – восстали против Господа!","10":"Раскрыла тогда земля свой зев и поглотила их; вместе с Кореем погибли и все его сообщники. Двести пятьдесят человек уничтожил огонь – как знамение и предупреждение.","11":"Однако сыновья Корея не погибли.)","12":"Потомки Симеона, по родам: от Немуэла – род Немуэла, от Ямина – род Ямина, от Яхина – род Яхина,","13":"от Зераха – род Зераха, от Саула – род Саула.","14":"Это роды потомков Симеона – двадцать две тысячи двести человек.","15":"Потомки Гада, по родам: от Цефона – род Цефона, от Хагги – род Хагги, от Шуни – род Шуни,","16":"от Озни – род Озни, от Эри – род Эри,","17":"от Арода – род Арода, от Арели – род Арели.","18":"Это роды потомков Гада; в списки было внесено сорок тысяч пятьсот человек.","19":"Сыновья Иуды: Эр и Онан (оба умерли в Ханаане).","20":"Потомки Иуды, по родам: от Шелы – род Шелы, от Пареца – род Пареца, от Зараха – род Зараха.","21":"Потомки Пареца: от Хецрбна – род Хецрона, от Хамула – род Хамула.","22":"Это роды потомков Иуды; в списки было внесено семьдесят шесть тысяч пятьсот человек.","23":"Потомки Иссахара, по родам: от Толы – род Толы, от Пуввы – род Пуввы,","24":"от Яшува – род Яшува, от Шимрона – род Шимрона.","25":"Это роды потомков Иссахара; в списки было внесено шестьдесят четыре тысячи триста человек.","26":"Потомки Завулона, по родам: от Середа – род Середа, от Элона – род Элона, от Яхлеэла – род Яхлеэла.","27":"Это роды потомков Завулона; в списки было внесено шестьдесят тысяч пятьсот человек.","28":"Потомки Иосифа (Манассии и Ефрема), по родам:","29":"Потомки Манассии: от Махира – род Махира. У Махира был сын Галаад: от Галаада – род Галаада.","30":"Вот потомки Галаада: Иэзер, род Иэзера, от Хелека – род Хелека,","31":"Асриэл, род Асриэла, Шехем, род Шехема,","32":"Шемида, род Шемиды, Хефер, род Хефера.","33":"У Целофхада, сына Хефера, не было сыновей, а только дочери. Имена дочерей Целофхада: Махла, Ноа, Хогла, Милька и Тирца .","34":"Это роды потомков Манассии; в списки было внесено пятьдесят две тысячи семьсот человек.","35":"Потомки Ефрема, по родам: от Шутелаха – род Шутелаха, от Бехера – род Бехера, от Тахана – род Тахана.","36":"Вот потомки Шутелаха: от Эрана – род Эрана.","37":"Это роды потомков Ефрема; в списки было внесено тридцать две тысячи пятьсот человек. Таковы потомки Иосифа, по родам.","38":"Потомки Вениамина, по родам: от Белы – род Белы, от Ашбела – род Ашбела, от Ахирама – род Ахирама,","39":"от Шефуфама – род Шефуфама, от Хуфама – род Хуфама.","40":"У Белы были сыновья Ард и Нааман: от Арда – род Арда, от Наамана – род Наамана.","41":"Это потомки Вениамина, по родам; в списки было внесено сорок пять тысяч шестьсот человек.","42":"Потомки Дана, по родам: от Шухама – род Шухама. Это роды потомков Дана.","43":"Всего в родах потомков Шухама было записано шестьдесят четыре тысячи четыреста человек.","44":"Потомки Асира, по родам: от Имны – род Имны, от Ишви – род Ишви, от Берии – род Берии.","45":"Потомки Берии: от Хевера – род Хевера, от Малкиэла – род Малкиэла.","46":"А дочь Асира звали Серах.","47":"Это роды потомков Асира; в списки было внесено пятьдесят три тысячи четыреста человек.","48":"Потомки Неффалима, по родам: от Яхцеэла – род Яхцеэла, от Гуни – род Гуни,","49":"от Иецера – род Иецера, от Шиллема – род Шиллема.","50":"Это роды потомков Неффалима; в списки было внесено сорок пять тысяч четыреста человек.","51":"Таковы итоги переписи сынов Израилевых: шестьсот одна тысяча семьсот тридцать человек.","52":"Господь сказал Моисею:","53":"«Земля должна быть роздана им во владение, по числу людей:","54":"многочисленным племенам дай большие наделы, малочисленным – малые наделы. Пусть каждое племя получит надел в соответствии с числом людей, по списку.","55":"Землю же следует распределять по жребию; на каждое племя по наделу.","56":"И большие, и малые племена должны получать наделы по жребию».","57":"Вот итоги переписи потомков Левия, по родам: от Гершона – род Гершона, от Кехата – род Кехата, от Мерари – род Мерари.","58":"(Роды потомков Левия: род Ливни, род Хеврона, род Махли, род Муши, род Корея.) У Кехата был сын Амрам.","59":"Жену Амрама звали Иохевед, дочь Левия (она родилась у Левия в Египте). Иохевед родила Амраму Аарона, Моисея и их сестру Мирьям.","60":"У Аарона были сыновья: Надав и Авиуд, Элеазар и Итамар.","61":"Надав и Авиуд погибли, когда принесли Господу чуждый огонь.","62":"Всего в список было внесено двадцать три тысячи левитов мужского пола в возрасте старше месяца. Они не были включены в списки сынов Израилевых, потому что, в отличие от остальных сынов Израилевых, не должны были получить надела.","63":"Таков был список сынов Израилевых, составленный Моисеем и священником Элеазаром на Моавской равнине, у Иордана, напротив Иерихона.","64":"В нем не осталось никого из списка, составленного Моисеем и священником Аароном в Синайской пустыне:","65":"ведь Господь сказал о всех тех людях, что они умрут в пустыне, – и вот, никого из них не осталось в живых, кроме Калева, сына Иефунне, и Иисуса Навина."},"27":{"1":"Пришли дочери Целофхада, который был сыном Хефера, сына Галаада, сына Махира, сына Манассии – он был из рода Манассии, сына Иосифа. Дочерей Целофхада звали Махла , Ноа, Хогла, Милька и Тирца .","2":"Они стали у входа в Шатер Встречи, перед Моисеем, священником Элеазаром, вождями и всей общиной, и сказали:","3":"«Наш отец умер в пустыне, за свои грехи. Но он не принадлежал к сообщникам Корея, бунтовавшим против Господа. Сыновей у него не было.","4":"Так неужели никто в нашем роду не унаследует имя нашего отца – лишь потому, что у него не было сыновей? Дай нам землю наравне с родичами нашего отца!»","5":"Моисей передал Господу их просьбу.","6":"И Господь сказал Моисею:","7":"«Правильно говорят дочери Целофхада. Дай им земельный надел наравне с родичами их отца, – пусть перейдет к ним надел отца.","8":"И скажи сынам Израилевым: если кто-нибудь из вас умрет, не оставив сына, то отдайте его надел дочери.","9":"Если у него нет и дочери, отдайте надел его братьям.","10":"Если у него нет братьев, отдайте надел братьям его отца.","11":"Если у его отца не было братьев, отдайте надел ближайшему кровному родственнику – пусть земля отойдет к нему. Это должно быть для сынов Израилевых законом, так повелел Господь Моисею».","12":"Господь сказал Моисею: «Взойди на горы Аварим и окинь взглядом страну, которую Я отдаю сынам Израилевым.","13":"Ты посмотришь на эту страну и отойдешь к предкам своим, как отошел к предкам твой брат Аарон.","14":"Ибо в пустыне Цин, когда община возроптала, вы ослушались Меня – там, при источнике вы не явили им Мою святость». (Это был источник Мериват – Кадеш в пустыне Цин.)","15":"Моисей сказал Господу:","16":"«Пусть Господь, Бог, дающий дыхание всему живому, поставит над общиной человека,","17":"который возглавит их в походе и при возвращении из похода, поведет их за собой и приведет назад. Пусть община Господня не будет как стадо без пастуха!»","18":"Господь сказал Моисею: «Позови Иисуса Навина – человека, в котором дух, – и возложи на него руку.","19":"Вели ему стать перед священником Элеазаром и перед всей общиной и у всех на глазах передай ему полномочия.","20":"Передай ему часть своей власти, чтобы вся община сынов Израилевых слушалась его.","21":"Он будет подходить к священнику Элеазару, и тот будет вопрошать для него Господа через урим. По указанию Господа они будут выступать в поход и по Его указанию возвращаться – Иисус и все сыны Израилевы, вся община».","22":"Моисей сделал так, как велел ему Господь: позвал Иисуса, поставил его перед священником Элеазаром и перед всей общиной,","23":"возложил на него руки и передал ему полномочия. Так повелел Господь через Моисея."},"28":{"1":"Господь сказал Моисею:","2":"«Вели сынам Израилевым следить за тем, чтобы они в назначенные дни совершали Мне приношение – приносили дары, угощение для Меня, благоуханный дым, приятный Мне.","3":"Скажи им: вот дары, которые вы должны приносить Господу. Каждый день – два годовалых ягненка без изъянов (это регулярное всесожжение:","4":"одного ягненка приноси в жертву утром, а другого вечером)","5":"и хлебное приношение: одна десятая эфы пшеничной муки, которая смочена четвертью гина вручную приготовленного оливкового масла.","6":"Таково регулярное всесожжение, учрежденное на горе Синай, это дар Господу, благоуханный дым, приятный Ему.","7":"К этому полагается возлияние – четверть гина на каждого ягненка; возливай в святилище хмельное для Господа!","8":"Второго ягненка приноси в жертву вечером, с таким же хлебным приношением и таким же возлиянием, как и утром; это дар Господу, благоуханный дым, приятный Ему.","9":"В субботу – два годовалых ягненка без изъянов и хлебное приношение: две десятых эфы пшеничной муки, которая смочена оливковым маслом, с возлиянием.","10":"Это – субботнее всесожжение, совершаемое по субботам вдобавок к регулярному всесожжению, с возлиянием.","11":"В новолуние приносите Господу жертву всесожжения – двух быков, одного барана и семь годовалых ягнят без изъянов.","12":"И хлебное приношение: на каждого быка – три десятых эфы пшеничной муки, которая смочена оливковым маслом, на барана – две десятых эфы пшеничной муки, которая смочена оливковым маслом,","13":"а на каждого ягненка – одна десятая эфы пшеничной муки, которая смочена оливковым маслом. Это – всесожжение, дар Господу, благоуханный дым, приятный Ему.","14":"И возлияние: полгина вина на быка, треть гина на барана и четверть гина на каждого ягненка. Таково всесожжение, совершаемое по новолуниям, в каждое из новолуний года.","15":"Сверх регулярного всесожжения, закалывайте козла как очистительную жертву Господу, с возлиянием.","16":"В четырнадцатый день первого месяца – Пасха Господня.","17":"В пятнадцатый день этого месяца – Праздник. Семь дней ешьте пресный хлеб.","18":"Первый день да будет священным – не делайте в этот день никакой работы.","19":"Приносите Господу дар, жертву всесожжения – двух быков, одного барана и семь годовалых ягнят; все они должны быть без изъянов.","20":"Сопровождайте это хлебным приношением из пшеничной муки, которая смочена оливковым маслом: три десятых эфы на каждого быка, две десятых эфы на барана","21":"и по одной десятой эфы на каждого из семи ягнят.","22":"Кроме того, закалывайте козла как очистительную жертву, для вашего искупления.","23":"Все эти жертвы должны прибавляться к регулярному утреннему всесожжению.","24":"Совершайте такие жертвоприношения каждый день, все эти семь дней, вдобавок к регулярному всесожжению, с возлиянием. Это дар, угощение для Господа, благоуханный дым, приятный Ему.","25":"А седьмой день да будет для вас священным – не делайте в этот день никакой работы.","26":"День первого урожая, когда вы совершаете хлебное приношение Господу из нового урожая, – праздник Недель – да будет для вас священным; не делайте в этот день никакой работы.","27":"Принесите в жертву двух быков, одного барана и семь годовалых ягнят – как всесожжение, благоуханный дым, приятный Господу.","28":"Сопровождайте это хлебным приношением из пшеничной муки, смоченной оливковым маслом: три десятых эфы на каждого быка, две десятых эфы на барана","29":"и по одной десятой эфы на каждого из семи ягнят.","30":"Кроме того, принесите в жертву козла, для вашего искупления.","31":"Эти жертвы должны прибавляться к регулярному всесожжению и хлебному приношению, с возлияниями. Жертвенные животные должны быть без изъянов."},"29":{"1":"Первый день седьмого месяца да будет для вас священным – не делайте никакой работы. Это день, когда трубят в трубы.","2":"Принесите в жертву быка, барана и семь годовалых ягнят без изъянов – как всесожжение, как благоуханный дым, приятный Господу.","3":"Сопровождайте жертвоприношение хлебным приношением из пшеничной муки, которая смочена оливковым маслом: три десятых эфы на быка, две десятых эфы на барана","4":"и по одной десятой эфы на каждого из семи ягнят.","5":"Кроме того, принесите в жертву козла – как очистительную жертву, для вашего искупления.","6":"Эти жертвы должны прибавляться к жертвам, положенным в новолуния, и к регулярным всесожжениям, с хлебными приношениями и возлияниями. Это дар Господу, благоуханный дым, приятный Ему.","7":"Десятый день седьмого месяца да будет для вас священным – поститесь и не делайте в этот день никакой работы.","8":"Принесите в жертву быка, барана и семь годовалых ягнят – как всесожжение Господу, как благоуханный дым, приятный Ему; жертвенные животные должны быть без изъянов.","9":"Сделайте также хлебное приношение из пшеничной муки, которая смочена оливковым маслом: три десятых эфы на быка, две десятых эфы на барана","10":"и по одной десятой эфы на каждого из семи ягнят.","11":"Кроме того, принесите в жертву козла – как очистительную жертву. Эти жертвы должны прибавляться к очистительным жертвам Дня Очищения и к регулярным всесожжениям, с их хлебными приношениями и возлияниями.","12":"Пятнадцатый день седьмого месяца да будет для вас священным – не делайте в этот день никакой работы. Семь дней справляйте праздник Господень.","13":"Принесите в жертву тринадцать быков, двух баранов и четырнадцать годовалых ягнят – как всесожжение, как дар Господу, как благоуханный дым, приятный Ему; жертвенные животные должны быть без изъянов.","14":"Сопровождайте жертвоприношение хлебным приношением из пшеничной муки, которая смочена оливковым маслом: по три десятых эфы на каждого из тринадцати быков, по две десятых эфы на каждого из двух баранов","15":"и по одной десятой эфы на каждого из четырнадцати ягнят.","16":"Кроме того, принесите в жертву козла – как очистительную жертву. Эти жертвы должны прибавляться к регулярным всесожжениям с хлебным приношением и возлиянием.","17":"Во второй день: двенадцать быков, два барана и четырнадцать годовалых ягнят без изъянов.","18":"Жертвоприношение быков, баранов и ягнят должно сопровождаться положенным хлебным приношением и возлиянием – в соответствии с числом жертвенных животных.","19":"И козел – очистительная жертва. Эти жертвы должны прибавляться к регулярным всесожжениям с хлебным приношением и возлиянием.","20":"В третий день: одиннадцать быков, два барана и четырнадцать годовалых ягнят без изъянов.","21":"Жертвоприношение быков, баранов и ягнят должно сопровождаться положенным хлебным приношением и возлиянием – в соответствии с числом жертвенных животных.","22":"И козел – очистительная жертва. Эти жертвы должны прибавляться к регулярным всесожжениям с хлебным приношением и возлиянием.","23":"В четвертый день: десять быков, два барана и четырнадцать годовалых ягнят без изъянов.","24":"Жертвоприношение быков, баранов и ягнят должно сопровождаться положенным хлебным приношением и возлиянием – в соответствии с числом жертвенных животных.","25":"И козел – очистительная жертва. Эти жертвы должны прибавляться к регулярным всесожжениям с хлебным приношением и возлиянием.","26":"В пятый день: девять быков, два барана и четырнадцать годовалых ягнят без изъянов.","27":"Жертвоприношение быков, баранов и ягнят должно сопровождаться положенным хлебным приношением и возлиянием – в соответствии с числом жертвенных животных.","28":"И козел – очистительная жертва. Эти жертвы должны прибавляться к регулярным всесожжениям с хлебным приношением и возлиянием.","29":"В шестой день: восемь быков, два барана и четырнадцать годовалых ягнят без изъянов.","30":"Жертвоприношение быков, баранов и ягнят должно сопровождаться положенным хлебным приношением и возлиянием – в соответствии с числом жертвенных животных.","31":"И козел – очистительная жертва. Эти жертвы должны прибавляться к регулярным всесожжениям с хлебным приношением и возлиянием.","32":"В седьмой день: семь быков, два барана и четырнадцать годовалых ягнят без изъянов.","33":"Жертвоприношение быков, баранов и ягнят должно сопровождаться положенным хлебным приношением и возлиянием – в соответствии с числом жертвенных животных.","34":"И козел – очистительная жертва. Эти жертвы должны прибавляться к регулярным всесожжениям с хлебным приношением и возлиянием.","35":"Восьмой день – завершающий день праздника; не делайте в этот день никакой работы.","36":"Принесите в жертву быка, барана и семь годовалых ягнят без изъянов – как всесожжение, как дар Господу и благоуханный дым, приятный Ему.","37":"Жертвоприношение быков, баранов и ягнят должно сопровождаться положенным хлебным приношением и возлиянием – в соответствии с числом жертвенных животных.","38":"И козел – очистительная жертва. Эти жертвы должны прибавляться к регулярным всесожжениям с хлебным приношением и возлиянием.","39":"Приносите все эти жертвы Господу в назначенные дни – помимо ваших жертв по обету и добровольных жертв, будь то всесожжение, хлебное приношение, возлияние или пиршественная жертва»."},"30":{"1":"И Моисей передал сынам Израилевым все, что повелел ему Господь.","2":"Моисей сказал главам племен Израиля: «Вот что повелевает Господь.","3":"Если мужчина дал обет Господу или же, поклявшись, взял на себя обязательство, он не должен нарушать свое слово – пусть исполнит все, что пообещал.","4":"Если женщина, живущая, пока она не замужем, в доме отца, дала обет Господу или взяла на себя обязательство,","5":"а отец, узнав о ее обете или взятом ею обязательстве, промолчал, то любой ее обет или взятое ею обязательство сохраняет силу.","6":"Но если отец, узнав, запретил ей, то любой ее обет или взятое ею обязательство теряет силу. Господь простит ее, ибо это отец запретил ей.","7":"Если женщина вышла замуж, будучи связанной обетом или необдуманно взятым обязательством,","8":"а ее муж, узнав об этом, промолчал, то ее обет или взятое ею обязательство сохраняет силу.","9":"Если же ее муж, узнав, запретил ей, то этим он отменил ее обет или необдуманно взятое ею обязательство. Господь простит ее.","10":"Всякий обет, данный вдовою или разведенной, всякое обязательство, какое она на себя взяла, сохраняет силу.","11":"Если женщина, живя в доме мужа, дала обет или же, поклявшись, взяла на себя обязательство,","12":"а муж, узнав об этом, промолчал и не запретил ей, то любой ее обет или взятое ею обязательство сохраняет силу.","13":"Но если муж, узнав, отменил ее обещание, то это обещание – обет или обязательство – теряет силу. Это обещание было отменено ее мужем, и Господь простит ее.","14":"Любой обет, любая клятва смирять себя, которую дала жена, должны быть подтверждены либо отменены ее мужем.","15":"Если муж ничего не сказал ей в течение дня, то этим он подтвердил ее обет или обязательство – подтвердил тем, что узнал, но промолчал.","16":"Если муж отменит ее обещание позднее, то он в ответе за неисполнение обещанного».","17":"Таковы предписания, которые Господь дал Моисею. Это предписания для мужа и жены, а также для отца и дочери, живущей, пока не замужем, в доме отца."},"31":{"1":"Господь сказал Моисею:","2":"«Отомсти мидьянитянам за их преступления перед сынами Израилевыми, а потом отойдешь к предкам своим».","3":"Моисей сказал народу: «Соберите воинов для похода. Пусть они идут на мидьянитян и свершат мщение Господне над Мидьяном.","4":"Отправьте в поход по тысяче воинов от каждого из племен Израиля».","5":"И отобрали средь тысячных отрядов израильских двенадцать тысяч воинов – по тысяче от каждого племени.","6":"Моисей отправил их в поход, по тысяче от каждого племени, под руководством священника Пинехаса, сына Элеазара, со священной утварью и сигнальными трубами.","7":"Они напали на мидьянитян, как повелел Господь Моисею, и перебили всех мужчин этого племени.","8":"Они убили пять мидьянских царей – Эви, Рекема, Цура, Хура и Реву – и сразили мечом Валаама, сына Беора.","9":"Сыны Израилевы захватили в Мидьяне женщин, малых детей, и весь скот, и все стада; все их имущество они разграбили,","10":"а все города, в которых жили мидьянитяне, и все их становья сожгли.","11":"Они забрали всю добычу, все захваченное, и людей, и скот,","12":"и привели пленников, вместе со всем захваченным, со всей добычей, к Моисею, священнику Элеазару и общине сынов Израилевых в свой стан, что находился на Моавской равнине, у Иордана, напротив Иерихона.","13":"Моисей, священник Элеазар и все вожди общины вышли из стана навстречу войску.","14":"Моисей был в гневе на возвращающихся из похода военачальников, начальников тысячных отрядов и начальников сотен.","15":"Он сказал им: «Вы оставили всех женщин в живых?","16":"А ведь это именно они, по подсказке Валаама, склонили сынов Израилевых к преступлению против Господа, к пеорскому отступничеству, и в общине Господней начался мор.","17":"Убейте всех мальчиков и убейте всех женщин, которые познали мужчину!","18":"А девиц, еще не познавших мужчину, оставьте в живых, для себя.","19":"Сами семь дней оставайтесь вне стана. И вы сами, и ваши пленные – все, кто убил человека или прикоснулся к убитому, должны пройти очищение, на третий день и на седьмой день.","20":"Очищению подлежит также всякая одежда, любая вещь из кожи или козьей шерсти и любая деревянная вещь».","21":"Священник Элеазар сказал воинам, участникам сражений: «Вот правило, которое Господь предписал Моисею:","22":"золото и серебро, медь и железо, олово и свинец –","23":"все, что выдерживает огонь, – очистите огнем и промойте водой очищения. Тогда оно станет чистым. То, что не выдержит огня, очищайте водой.","24":"На седьмой день постирайте свою одежду – и станете чисты. Тогда вы сможете войти в стан».","25":"Господь сказал Моисею:","26":"«Вместе со священником Элеазаром и главами родов общины пересчитай захваченных людей и скот.","27":"Раздели добычу на две равные части – для воинов, ходивших в поход, и для остальной общины.","28":"Собери дань для Господа. Из доли воинов, ходивших в поход, следует взять по одному человеку, быку, ослу или барану из каждых пятисот.","29":"Возьми это из их доли и отдай священнику Элеазару как подношение Господу.","30":"А из доли остальных сынов Израилевых возьми по одному человеку, быку, ослу или барану из каждых пятидесяти – и отдай левитам, хранителям скинии Господней».","31":"Моисей и священник Элеазар сделали так, как повелел Господь Моисею.","32":"Добыча – то, что осталось от захваченного воинами – составляла шестьсот семьдесят пять тысяч голов мелкого скота,","33":"семьдесят две тысячи голов крупного скота,","34":"шестьдесят одну тысячу ослов","35":"и тридцать две тысячи пленниц – девушек, еще не познавших мужчину.","36":"Доля ходивших в поход (половина всей добычи) составила триста тридцать семь тысяч пятьсот голов мелкого скота","37":"(из них шестьсот семьдесят пять голов – дань Господу),","38":"тридцать шесть тысяч голов крупного скота (из них семьдесят две головы – дань Господу),","39":"тридцать тысяч пятьсот ослов (из них шестьдесят один – дань Господу)","40":"и шестнадцать тысяч пленниц (из них тридцать две – дань Господу).","41":"Эту дань – подношения Господу – Моисей передал священнику Элеазару, как и повелел Моисею Господь.","42":"Доля же остальных сынов Израилевых (то, что Моисей забрал для них у участников похода,","43":"доля общины) составила триста тридцать семь тысяч пятьсот голов мелкого скота,","44":"тридцать шесть тысяч голов крупного скота,","45":"тридцать тысяч пятьсот ослов","46":"и шестнадцать тысяч пленниц.","47":"Из доли сынов Израилевых Моисей взял по одной пленнице и по одному животному из каждых пятидесяти – и отдал левитам, хранителям скинии Господней, как и повелел Моисею Господь.","48":"К Моисею пришли военачальники, начальники тысячных отрядов и начальники сотен.","49":"Они сказали Моисею: «Мы, рабы твои, пересчитали своих воинов: пропавших нет.","50":"И вот наше приношение Господу, в выкуп за нашу жизнь – добытое нами золото: застежки, браслеты, кольца, серьги и ожерелья».","51":"Моисей и священник Элеазар приняли у них золото – все эти золотые вещи.","52":"Все золото, которое начальники тысячных отрядов и начальники сотен принесли в дар Господу, весило шестнадцать тысяч семьсот пятьдесят шекелей.","53":"(Воины же оставили свою добычу себе.)","54":"Приняв золото от начальников тысячных отрядов и начальников сотен, Моисей и священник Элеазар отнесли его в Шатер Встречи – там оно будет напоминанием о сынах Израилевых перед Господом."},"32":{"1":"У потомков Рувима и потомков Гада было очень много скота. Увидев, что область Язера и область Галаада – это хорошие пастбища для скота,","2":"потомки Гада и потомки Рувима пришли к Моисею, священнику Элеазару и вождям общины и сказали:","3":"«Атарот, Дивон, Язер, Нимра, Хешбон, Эльале, Севам, Нево и Беон –","4":"земля, которую Господь покорил для общины Израиля, – это хорошие пастбища для скота. А мы, рабы твои, пасем скот».","5":"Они сказали: «Окажи милость, пусть эта земля будет отдана нам, рабам твоим. Не веди нас за Иордан».","6":"Но Моисей сказал потомкам Гада и потомкам Рувима: «Неужели ваши братья пойдут воевать, а вы останетесь здесь?","7":"Зачем вы хотите смутить сынов Израилевых, чтобы они не шли в страну, которую Господь отдает им?","8":"Так поступили ваши отцы, когда я послал их из Кадеш – Барнеа осмотреть эту страну.","9":"Они дошли до долины Эшкол и осмотрели страну, а потом стали смущать сынов Израилевых, чтобы они не шли в страну, которую Господь отдает им.","10":"Тогда разгорелся гнев Господа, и Он поклялся:","11":"„Никто из тех, кто вышел из Египта, из тех, кто старше двадцати, из тех, что изменили Мне, не увидит землю, которую Я поклялся отдать Аврааму, Исааку и Иакову, –","12":"никто, кроме Калева, сына Иефунне , кениззея, и Иисуса Навина, которые остались верны Господу\".","13":"И разгорелся гнев Господа на сынов Израилевых, и Он заставил их сорок лет блуждать по пустыне, пока не умерло все поколение тех, кто совершил дело, ненавистное Господу.","14":"А теперь вы делаете то же, что и ваши отцы, – вы, порождение грешников, хотите опять навлечь на Израиль гнев Господа!","15":"Если вы отвернетесь от Господа, Он снова оставит сынов Израилевых в пустыне – вы погубите весь народ!»","16":"Тогда, представ пред Моисеем, они сказали: «Мы построим здесь загоны для наших стад и города для наших детей,","17":"а сами пойдем в боевом строю в первых рядах сынов Израилевых – и приведем их на их землю. Дети наши останутся в укрепленных городах, где они будут защищены от местных жителей,","18":"а мы не вернемся домой, пока каждый из сынов Израилевых не получит свой надел.","19":"Мы не станем брать себе надела вместе с ними – по ту сторону Иордана, ибо наши наделы – здесь, к востоку от Иордана».","20":"Моисей им ответил: «Если вы сделаете так, как сказали, если пойдете перед Господом на битву,","21":"если все ваши воины пойдут за Иордан перед Господом и будут сражаться, пока Он не отберет землю у Своих врагов,","22":"пока страна не покорится Господу, – тогда вы, вернувшись, будете неповинны пред Господом и пред Израилем, тогда земля эта будет в глазах Господа вашим владением.","23":"А если вы не сделаете так, то согрешите против Господа – и знайте: ваш грех вас настигнет!","24":"Так что постройте города для детей ваших и загоны для ваших стад – и исполняйте обещанное». \"Потомки Гада и потомки Рувима сказали Моисею: «Мы, рабы твои, сделаем, как велит господин наш.","26":"Наши дети и жены и наши стада, весь скот наш, останутся тут, в городах Галаада,","27":"а мы, рабы твои, все наши воины, пойдем перед Господом на битву, как повелел господин наш».","28":"Моисей отдал священнику Элеазару, Иисусу Навину и главам родов племен Израилевых такие распоряжения:","29":"«Если потомки Гада и потомки Рувима пойдут с вами за Иордан, если все их воины пойдут перед Господом на битву, то когда эта страна будет вами покорена, отдайте им во владение Галаад.","30":"Но если они не пойдут вместе с вами, в первых рядах, то пусть их наделы будут, наряду с вашими, в Ханаане».","31":"Потомки Гада и потомки Рувима сказали: «Как повелел Господь нам, рабам твоим, так мы и сделаем.","32":"Мы в первых рядах, перед Господом, пойдем в Ханаан – а наделы наши пусть будут за Иорданом».","33":"Тогда Моисей отдал потомкам Гада и потомкам Рувима, а также половине племени Манассии, сына Иосифа, царство Сихона, царя аморейского, и царство Ога, царя башанского – землю и города с их окрестностями.","34":"Потомки Гада отстроили Дивон, Атарбт, Ароэр,","35":"Атрот – Шофан, Язtэр, Иогбеху ,","36":"Бет – Нимру и Бет – Харан – укрепленные города, загоны для стад.","37":"Потомки Рувима отстроили Хешбон, Эльале, Кирьятаим,","38":"Нево, Баал – Меон (этим городам были даны другие имена), а также Сивму. Этим отстроенным городам они давали новые имена.","39":"Потомки Махира, сына Манассии, пришли в Галаад и захватили его, стали жить на месте обитавших там прежде амореев.","40":"Моисей отдал Галаад потомкам Махира, сына Манассии, и те поселились в Галааде.","41":"Яир, сын Манассии, захватил деревни Гамовы и назвал их Яировыми Деревнями.","42":"Новах завоевал Кенат с окрестными селениями и назвал этот город своим именем – Новах."},"33":{"1":"Вот переходы, совершенные сынами Израилевыми, после того как их воинства вышли из Египта под началом Моисея и Аарона.","2":"(Моисей составил список стоянок, откуда они выступали в поход по указанию Господа.) Вот их переходы и стоянки.","3":"В первый месяц, в пятнадцатый день первого месяца сыны Израилевы покинули Раамсес. Они отправились в путь на следующий день после Пасхи, смело, ничего не опасаясь, на глазах у всех египтян.","4":"А египтяне хоронили своих первенцев, которых убил Господь – покарал Господь богов Египта!","5":"Покинув Раамсес, сыны Израилевы остановились в Суккоте.","6":"Покинув Суккот, они остановились в Этаме, на краю пустыни.","7":"Покинув Этам, они повернули назад, к Пи – Хахироту, что близ Баал – Цефона, и остановились возле Мигдола.","8":"Покинув ПиХахирот, они перешли через море и оказались в пустыне. Три дня шли они по пустыне Этам и остановились в Маре .","9":"Покинув Мару, они пришли в Элим. В Элиме было двенадцать источников и семьдесят финиковых пальм; там они сделали остановку.","10":"Покинув Элим, они остановились у моря Суф.","11":"Покинув стоянку у моря Суф, они остановились в пустыне Син.","12":"Покинув пустыню Син, они остановились в Дофке .","13":"Покинув Дофку, они остановились в Алуше.","14":"Покинув Алуш, они остановились в Рефидиме. Там не было воды для питья.","15":"Покинув Рефидим, они остановились в Синайской пустыне.","16":"Покинув Синайскую пустыню, они остановились в Киврот – ха – Тааве .","17":"Покинув Киврот – ха – Тааву, они остановились в Хацероте.","18":"Покинув Хацерот, они остановились в Ритме .","19":"Покинув Ритму, они остановились в Риммон – Пареце.","20":"Покинув Риммон – Парец, они остановились в Ливне .","21":"Покинув Ливну, они остановились в Риссе .","22":"Покинув Риссу, они остановились в Кехелате.","23":"Покинув Кехелату, они остановились у горы Шефер.","24":"Покинув гору Шефер, они остановились в Хараде .","25":"Покинув Хараду, они остановились в Макхелоте.","26":"Покинув Макхелот, они остановились в Тахате.","27":"Покинув Тахат, они остановились в Терахе.","28":"Покинув Терах, они остановились в Митке .","29":"Покинув Митку, они остановились в Хашмоне .","30":"Покинув Хашмону, они остановились в Мосероте.","31":"Покинув Мосерот, они остановились в Бене –Яакане.","32":"Покинув Бене – Яакан, они остановились в Хор – Хаггидгаде.","33":"Покинув Хор – Хаггидгад, они остановились в Иотвате.","34":"Покинув Иотвату, они остановились в Авроне .","35":"Покинув Аврону, они остановились в Эцион – Гевере.","36":"Покинув Эцион – Гевер, они остановились в пустыне Цин, в Кадеше.","37":"Покинув Кадеш, они остановились у горы Ор, близ границы Эдома.","38":"По указанию Господа священник Аарон взошел на гору Ор и там умер; это было на сороковой год после ухода сынов Израилевых из Египта, в первый день пятого месяца.","39":"Сто двадцать три года было Аарону, когда он умер на горе Ор.","40":"В ту пору царь Арада, ханааней, правивший в Негеве, в Ханаане, узнал о приходе сынов Израилевых…","41":"Покинув гору Ор, они остановились в Цалмоне .","42":"Покинув Цалмону, они остановились в Пуноне.","43":"Покинув Пунон, они остановились в Овоте.","44":"Покинув Овот, они остановились в Ийе–ха – Авариме, в Моаве.","45":"Покинув Ийим, они остановились в Дивон – Гаде.","46":"Покинув Дивон – Гад, они остановились в Алмон – Дивлатаиме.","47":"Покинув Алмон – Дивлатаим, они остановились у гор Аварим, близ Нево .","48":"Покинув горы Аварим, они остановились на Моавской равнине, у Иордана, напротив Иерихона.","49":"Остановившись у Иордана, они расположились на Моавской равнине от Бет – Иешимота до Авел – Шиттима.","50":"Там, на Моавской равнине, у Иордана, напротив Иерихона, Господь сказал Моисею:","51":"«Скажи сынам Израилевым: когда вы перейдете на тот берег Иордана, в Ханаан,","52":"то отберите землю у прежних обитателей этой страны, уничтожьте все их барельефы, и все статуи уничтожьте, и разрушьте все их святилища.","53":"Отберите у них эту землю и поселитесь на ней, ибо Я отдаю ее вам во владение.","54":"Разделите землю по жребию между родами: многочисленным родам дайте большие наделы, малочисленным – малые наделы. Кому какая земля выпадет по жребию – ею он и будет владеть. Распределите наделы между племенами.","55":"Но если вы не отберете землю у жителей этой страны, то те, кого вы оставите, будут у вас что колючка в глазу, что шип в боку: они не дадут вам покоя на земле, на которой вы будет жить.","56":"Тогда все, что сейчас Я собираюсь сделать с ними, Я сделаю с вами!»"},"34":{"1":"Господь сказал Моисею:","2":"«Отдай сынам Израилевым такие распоряжения: скоро вы войдете в Ханаан. И вот земля, которая вам достанется (земля Ханаана, в его границах).","3":"На юге ваши владения будут начинаться от пустыни Цин и рубежей Эдома. Ваша южная граница будет начинаться от края Мертвого моря на востоке,","4":"затем, повернув, пройдет южнее Скорпионова подъема, минует Цин, с юга обогнет Кадеш – Барнеа, выйдет к Хацар – Аддару и минует Ацмон. Ют Ацмона граница пойдет по Египетской ложбине и достигнет моря.","6":"Вашей западной границей будет Великое море. Оно – ваша граница на западе.","7":"Вот ваша северная граница. Проведите ее от Великого моря до горы Ор,","8":"от горы Ор – до Лево –Хамата. Далее граница пойдет до Цедада,","9":"выйдет к Зифрону и достигнет Хацар – Энана. Это ваша северная граница.","10":"Вашу восточную границу проведите от Хацар – Энана до Шефама;","11":"от Шефама она спустится до Ривлы, что к востоку от Аина, и пойдет дальше вниз, до восточного берега озера Киннерет.","12":"Затем граница пойдет вниз вдоль Иордана, до Мертвого моря. Это будет ваша страна. Таковы ее границы».","13":"Моисей передал эти распоряжения сынам Израилевым и сказал им: «Это земля, которую вы должны разделить между собой по жребию; Господь велел отдать ее девяти с половиной племенам.","14":"Племя потомков Рувима (все роды Рувимовы) и племя потомков Гада (все роды Гадовы) уже получили свои наделы, как и половина племени Манассии.","15":"Эти два с половиной племени получили свои наделы к востоку от Иордана, напротив Иерихона, – на восточном берегу реки».","16":"Господь сказал Моисею:","17":"«Вот имена тех, кто будет делить между вами эту землю: священник Элеазар и Иисус Навин.","18":"И еще возьмите для раздела земли по одному вождю от каждого племени.","19":"Вот их имена: от племени Иуды – Калев, сын Иефунне ,","20":"от племени Симеона – Самуил, сын Аммихуда,","21":"от племени Вениамина – Элидад, сын Кислона,","22":"от племени Дана – вождь Букки, сын Иогли ,","23":"из потомков Иосифа: от племени Манассии – вождь Ханниэл, сын Эфода,","24":"а от племени Ефрема – вождь Кемуэл, сын Шифтана,","25":"от племени Завулона – вождь Элицафан, сын Парнаха,","26":"от племени Иссахаpa – вождь Палтиэл, сын Аззана,","27":"от племени Асира – вождь Ахихуд, сын Шеломи ,","28":"от племени Неффалима – вождь Педаэл, сын Аммихуда».","29":"Это люди, которым Господь повелел разделить Ханаан между сынами Израилевыми."},"35":{"1":"На Моавской равнине, у Иордана, напротив Иерихона, Господь сказал Моисею:","2":"«Вели сынам Израилевым, чтобы они выделили в своих наделах города для левитов. Отдайте левитам также и пастбища вокруг этих городов.","3":"Пусть они живут в городах, а на пастбищах держат скот – свои стада, своих животных.","4":"Пастбища при тех городах, которые вы отдадите левитам, должны простираться на тысячу локтей от городской стены, во все стороны.","5":"Отмерьте с востока от города границу в две тысячи локтей, с юга границу в две тысячи локтей, с запада границу в две тысячи локтей, и с севера границу в две тысячи локтей, так чтобы город был посередине. Таковы должны быть пастбища при левитских городах.","6":"Города, которые вы отдадите левитам, это шесть городов для убежища, куда сможет бежать убийца, и еще сорок два города.","7":"Всего вы должны передать левитам сорок восемь городов, с пастбищами при них.","8":"Выделяя левитам города из владений сынов Израилевых, у большого племени берите больше городов, у малого – меньше. Пусть число городов, которые племя отдает левитам, будет соразмерно наделу, который достанется этому племени».","9":"Господь сказал Моисею:","10":"«Передай сынам Израилевым: когда вы, перейдя Иордан, войдете в землю ханаанскую,","11":"изберите себе города для убежища, куда сможет бежать всякий, кто совершит неумышленное убийство.","12":"В этих городах ему можно будет найти убежище от кровной мести: убийцу не следует предавать смерти, пока он не предстанет перед судом общины.","13":"Вы должны выделить для убежища шесть городов:","14":"три города за Иорданом и три города в Ханаане. Это будут города для убежища.","15":"И для сынов Израилевых, и для живущих среди них переселенцев эти шесть городов будут убежищем, куда сможет бежать всякий, кто совершит неумышленное убийство.","16":"Если один человек ударит другого железным орудием и тот умрет, этот человек – убийца. Убийца должен быть предан смерти.","17":"Если один человек ударит другого каменным орудием, которым можно убить человека, и тот умрет, этот человек – убийца. Убийца должен быть предан смерти.","18":"Если один человек ударит другого деревянным орудием, которым можно убить человека, и тот умрет, этот человек – убийца. Убийца должен быть предан смерти.","19":"Где бы мститель не застиг убийцу, он может умертвить его.","20":"Если один человек из ненависти толкнет другого или умышленно бросит в него чем-нибудь и тот умрет,","21":"или по злобе ударит его рукой, так что тот умрет, то этот человек должен быть предан смерти как убийца. Где бы мститель не застиг убийцу, он может умертвить его.","22":"Но если один человек, не испытывая вражды, случайно толкнет другого, или же без умысла попадет в него брошенным предметом,","23":"или по оплошности уронит на него камень, способный убить, и тот умрет – а убивший не был ему врагом и не замышлял против него зла –","24":"тогда община должна выступить как судья между случайным убийцей и мстителем, руководствуясь этими правилами.","25":"Община должна защитить убийцу от мстителя, доставив его в город – убежище, где он может укрыться. Пусть он живет там до смерти верховного священника, помазанного священным маслом.","26":"Если же он покинет пределы города – убежища, в котором он решил укрыться,","27":"а мститель встретит его за пределами этого города и убьет, то мститель будет неповинен.","28":"Убийца должен оставаться в городе – убежище до смерти верховного священника. Только после смерти верховного священника он может вернуться на свою землю.","29":"Соблюдайте этот закон из рода в род, где бы вы ни жили.","30":"В случае убийства убийцу можно казнить, только если есть показания свидетелей. Показаний одного свидетеля недостаточно для казни.","31":"Не берите выкупа за жизнь убийцы, которого следует казнить, – он должен быть предан смерти.","32":"И за жизнь того, кто укрылся в городе – убежище, не берите выкупа, чтобы он мог вернуться и жить на своей земле еще до смерти верховного священника.","33":"Не оскверняйте землю, на которой вы обитаете. Ибо кровь оскверняет землю и нет для земли другого выкупа за пролитую кровь, кроме крови того, кто ее пролил.","34":"Не делайте нечистой землю, на которой вы живете, землю, на которой Я пребываю. Ибо Я, Господь, пребываю среди сынов Израилевых»."},"36":{"1":"Пришли предводители родов, происходящих от Галаада, сына Махира, сына Манассии, из потомков Иосифа. Они обратились к Моисею, а также к вождям, главам родов сынов Израилевых,","2":"с такими словами: «Господь велел тебе, господину нашему, раздать по жребию землю во владение сынам Израилевым. Ты, господин наш, получил от Господа повеление отдать надел нашего родича Целофхада его дочерям.","3":"Но если они выйдут замуж за человека из другого племени сынов Израилевых, то их надел будет отрезан от надела наших предков и присоединен к наделу этого племени, так что надел, полученный нами по жребию, уменьшится.","4":"Когда у сынов Израилевых будет юбилейный год, надел этих женщин перейдет к племени их мужей – будет отрезан от надела нашего отчего племени».","5":"И Моисей, по указанию Господа, повелел сынам Израилевым: «Племя потомков Иосифа говорит правильно.","6":"Вот что повелевает Господь по поводу дочерей Целофхада. Они могут выходить замуж за кого захотят, но при условии, что этот человек принадлежит к одному из родов их отчего племени.","7":"Наделы сынов Израилевых не должны переходить от одного племени к другому; пусть каждый из сынов Израилевых держится того надела, который достался его отчему племени.","8":"Если в каком-либо из племен Израилевых дочь наследует отцовский надел, то она должна выйти замуж за человека, принадлежащего к одному из родов ее отчего племени, пусть каждый из сынов Израилевых хранит надел своих предков.","9":"Надел не должен переходить от одного племени к другому; пусть каждое племя сынов Израилевых удерживает свой надел».","10":"Дочери Целофхада поступили так, как повелел Господь Моисею.","11":"Все они – Махла , Тирца, Хогла, Милька и Ноа – вышли замуж за сыновей своих дядей.","12":"Они выбрали себе мужей из родов потомков Манассии, сына Иосифа, и их надел остался за их отчим племенем.","13":"Таковы повеления и законы, которые Господь дал через Моисея сынам Израилевым на Моавской равнине, у Иордана, напротив Иерихона."}};
